  "2 · Zweite KI als Ersatz (empfohlen)": "2 · Second AI as a spare (recommended)",
  "Springt ein, wenn Gemini ausgelastet oder nicht erreichbar ist. Der PC wählt die kostenlosen Modelle selbst aus.": "Steps in when Gemini is busy or unreachable. The PC picks the free models itself.",
