  "Fokus starten": "Start focus",
  "In diesem Fenster gibt es keine Spracherkennung – schreib stattdessen, oder öffne JARVIS im Browser (Chrome, Edge).": "There is no speech recognition in this window – type instead, or open JARVIS in a browser (Chrome, Edge).",
