  "Den Schlüssel trägst du am PC selbst ein (hier, im Fenster des Begleiters) – nicht vom Handy aus.": "You enter the key on the PC itself (in the companion's window) – not from a phone.",
  "Diesen Monat {u} von {m} Zeichen": "This month {u} of {m} characters",
  "Eine besonders natürliche Stimme von ElevenLabs. Sie ist aus, solange du sie nicht einschaltest. Der Text, den JARVIS spricht, geht dann über deinen PC an ElevenLabs (ein Dienst in den USA, nach deren Preisen); der Schlüssel bleibt auf dem PC. Nur Standardstimmen, Monatslimit einstellbar. Klappt etwas nicht, spricht JARVIS mit der Browser-Stimme.": "A particularly natural voice from ElevenLabs. It stays off until you switch it on. The text JARVIS speaks then goes via your PC to ElevenLabs (a service in the USA, at their prices); the key stays on the PC. Stock voices only, monthly limit adjustable. If something fails, JARVIS uses the browser voice.",
  "ElevenLabs hat keine Standardstimmen geliefert.": "ElevenLabs returned no stock voices.",
