  "cloudflared auf dem PC leitet eine https-Adresse auf http://localhost:8787 weiter. Die Adresse in Einstellungen → Verbindung als „Öffentliche Adresse“ eintragen. Schnell-Tunnel (trycloudflare.com) sind temporär und ändern sich bei jedem Start.": "cloudflared on the PC forwards an https address to http://localhost:8787. Enter the address under Settings → Connection as “Public address”. Quick tunnels (trycloudflare.com) are temporary and change on every start.",
  "den mitgelieferten Relay-Server auf einem kleinen Server mit https betreiben und im Companion eintragen.": "run the included relay server on a small server with https and enter it in the companion.",
