  "https-Adresse oder eigenes Bild hochladen": "https address or upload your own image",
  "Standard: die offizielle Download-Seite. Wird 2 Minuten nach dem Start und dann einmal täglich geprüft; bei einer neuen Version kommt eine Benachrichtigung. Leer = keine Prüfung. Es wird nie automatisch installiert.": "Default: the official download page. Checked 2 minutes after start and then once a day; a new version triggers a notification. Empty = no check. Never installed automatically.",
