  "Mikrofon funktioniert – Pegel im guten Bereich.": "Microphone works – level in a good range.",
  "Sehr leise. Näher ans Mikrofon gehen oder die Eingangslautstärke in Windows erhöhen.": "Very quiet. Move closer to the microphone or raise the input volume in Windows.",
  "Kein Signal. Stummschaltung, Kabel und Windows-Datenschutz (Mikrofonzugriff für Desktop-Apps) prüfen.": "No signal. Check mute, cable and Windows privacy (microphone access for desktop apps).",
  "Übersteuert. Eingangslautstärke in Windows etwas senken.": "Clipping. Lower the input volume in Windows a little.",
  "Live nur bei aktiver Durchleitung – oder den Mikrofon-Test starten.": "Live only while passthrough is active – or start the microphone test.",
