  "Spitze {p} %, Mittel {a} %": "Peak {p} %, average {a} %",
  "Der Test nimmt 4 Sekunden am PC auf und zeigt nur den Pegel. Es wird nichts gespeichert oder übertragen.": "The test records 4 seconds on the PC and only shows the level. Nothing is stored or transmitted.",
  "Layouts gehören zu jedem Gerät. Gespeichert wird der Name – auf anderen Geräten wird das Layout mit gleichem Namen genutzt, sonst bleibt deren Layout.": "Layouts belong to each device. The name is stored – other devices use their layout with the same name, otherwise they keep their own.",
  "„{n}“ (auf diesem Gerät nicht vorhanden)": "“{n}” (not on this device)",
  "Als ZIP ({s})": "As ZIP ({s})",
  "Automatisches Installieren kann nur der Windows-Begleiter. Sonst: neue EXE herunterladen, Begleiter beenden, Datei ersetzen, neu starten – deine Daten liegen getrennt im Datenordner.": "Only the Windows companion can install automatically. Otherwise: download the new EXE, quit the companion, replace the file, restart – your data is kept separately in the data folder.",
  "Behoben": "Fixed",
  "Datei": "File",
  "Dein Gerät zeigt noch eine gespeicherte ältere Fassung.": "Your device is still showing a stored older version.",
  "Dein PC (Begleiter)": "Your PC (companion)",
  "Der Begleiter startet mit der vorherigen Version neu. Deine Daten bleiben erhalten.": "The companion restarts with the previous version. Your data is kept.",
  "Der Download kommt direkt von der oben genannten Quelle, ohne Anmeldung. Windows SmartScreen kann warnen, weil die EXE kein gekauftes Code-Zertifikat hat – Echtheit über Signatur und Prüfsumme oben.": "The download comes directly from the source named above, no sign-in. Windows SmartScreen may warn because the EXE has no purchased code certificate – authenticity via the signature and checksum above.",
  "Details anzeigen": "Show details",
  "Die Versionsangaben konnten nicht geladen werden: {e}. Es wird kein Download angeboten, solange die Datei nicht bestätigt ist.": "The version information could not be loaded: {e}. No download is offered until the file is confirmed.",
  "Die Windows-Datei läuft nicht auf iPhone, iPad oder Android. Du kannst sie hier herunterladen und dann auf den PC bringen – z. B. über OneDrive/Google Drive/iCloud, per E-Mail an dich selbst, USB-Kabel oder den Netzwerkordner. Oder öffne diese Seite direkt am PC.": "The Windows file does not run on iPhone, iPad or Android. You can download it here and then move it to the PC – e.g. via OneDrive/Google Drive/iCloud, by e-mail to yourself, USB cable or a network folder. Or open this page directly on the PC.",
  "Diese Datei ist nicht signiert. Der Begleiter installiert sie nicht automatisch.": "This file is not signed. The companion will not install it automatically.",
  "Diese Version herunterladen": "Download this version",
  "Diese Webseite": "This website",
  "Eigene Quelle: {s}": "Own source: {s}",
  "Größe": "Size",
