  "Prüfen, Herunterladen und Installieren geht auch von hier (nicht während eines Spiels). Zurücksetzen und „automatisch installieren“ nur direkt am PC (Sicherheit).": "Checking, downloading and installing also work from here (not during a game). Rolling back and “install automatically” only directly at the PC (security).",
  "Dieses Gerät darf nur prüfen und herunterladen. Installieren braucht das Recht „Admin“ oder den PC selbst.": "This device may only check and download. Installing needs the “Admin” right or the PC itself.",
