  "Updates & Versionen": "Updates & versions",
  "Updates der offiziellen Quelle müssen mit dem Schlüssel des Projekts signiert sein. Eigene Quellen dürfen unsigniert sein und werden dann so gekennzeichnet.": "Updates from the official source must be signed with the project's key. Own sources may be unsigned and are then marked as such.",
  "Verbessert": "Improved",
  "Versionsverlauf anzeigen": "Show version history",
  "Vorher wird ein Wiederherstellungspunkt angelegt. Der Begleiter wird beendet, ersetzt und neu gestartet. Einstellungen, Spiele, Profile und Sounds bleiben erhalten.": "A restore point is created first. The companion is closed, replaced and restarted. Settings, games, profiles and sounds are kept.",
