  "Design übernommen": "Design applied",
  "Designs": "Designs",
  "Eigene oder fremde Plugins als .pglplugin-Datei. Die Datei wird zuerst vollständig geprüft (Testmodus) – installiert wird erst nach deiner Bestätigung, und zwar deaktiviert.": "Your own or third-party plugins as a .pglplugin file. The file is fully checked first (test mode) – it is only installed after your confirmation, and disabled.",
  "Eigener Katalog ohne gültige Signatur – alle Einträge gelten als nicht verifiziert.": "Own catalog without a valid signature – all entries count as unverified.",
