  "Nicht verifizierte Plugin-Dateien importieren darf nur der PC selbst oder ein Gerät mit Admin-Recht. Plugins aus dem Store gehen auch so.": "Only the PC itself or a device with admin rights may import unverified plugin files. Plugins from the store work anyway.",
