  "Plugin-Katalog (Store)": "Plugin catalog (store)",
  "Standard: offizieller, signierter Katalog des Projekts. Leer = kein Store; Plugin-Dateien lassen sich trotzdem importieren.": "Default: the project's official, signed catalog. Empty = no store; plugin files can still be imported.",
  "Abgebrochen": "Cancelled",
  "Automatisch: einmal pro Woche, vor jedem Update und vor jeder Wiederherstellung (ohne Audiodateien). Die letzten 5 automatischen Punkte bleiben erhalten.": "Automatic: once a week, before every update and before every restore (without audio files). The last 5 automatic points are kept.",
  "Berechne: {n} …": "Calculating: {n} …",
  "Bewertung": "Rating",
  "CPU": "CPU",
  "CPU-, RAM- und GPU-Auslastung alle 10 Sekunden, nur solange ein Spiel läuft. Bleibt auf dem PC.": "CPU, RAM and GPU load every 10 seconds, only while a game is running. Stays on the PC.",
  "CPU/GPU: Mittel / Spitze, gemessen alle 10 s während des Spiels (abschaltbar unter Einstellungen → Datenschutz). FPS misst Windows ohne Overlay nicht – daher keine FPS-Werte.": "CPU/GPU: average / peak, measured every 10 s during the game (can be switched off under Settings → Privacy). Windows does not measure FPS without an overlay – so there are no FPS values.",
  "Der PC fährt in {s} Sekunden herunter. Ungespeicherte Arbeit geht verloren.": "The PC shuts down in {s} seconds. Unsaved work is lost.",
  "Der PC geht in den Energiesparmodus. Die Verbindung bricht ab, bis er wieder aufwacht.": "The PC goes to sleep. The connection drops until it wakes up.",
  "Der PC startet in {s} Sekunden neu. Ungespeicherte Arbeit geht verloren.": "The PC restarts in {s} seconds. Unsaved work is lost.",
  "Der PC wird sofort gesperrt.": "The PC is locked immediately.",
  "Energie": "Power",
  "Energie-Aktionen sind nur im Windows-Begleiter verfügbar.": "Power actions are only available in the Windows companion.",
  "Energiesparen": "Sleep",
  "GPU": "GPU",
  "Geplantes Herunterfahren/Neustarten abbrechen": "Cancel scheduled shutdown/restart",
  "Größen werden berechnet – das kann bei großen Spielen dauern": "Calculating sizes – this can take a while for large games",
  "Größen werden nur auf Anfrage berechnet und gespeichert. * = einige Ordner waren nicht lesbar. Löschen/Deinstallieren bitte im jeweiligen Launcher.": "Sizes are only calculated and stored on request. * = some folders could not be read. Please delete/uninstall in the respective launcher.",
  "Herunterfahren": "Shut down",
  "Jeder PC behält seine eigenen Spiele, Profile, Sounds und Einstellungen. Es ist immer ein PC verbunden; Wechseln geht ohne neue Kopplung.": "Each PC keeps its own games, profiles, sounds and settings. One PC is connected at a time; switching works without pairing again.",
