  "Vergessen": "Forget",
  "Verlauf: letzte 30 Minuten, solange die Ansicht offen ist. Manche Router beantworten keinen Ping – dann zählt das als Verlust, obwohl das Internet geht.": "History: last 30 minutes while the view is open. Some routers do not answer pings – this counts as loss even though the internet works.",
  "Verlust {v}": "Loss {v}",
  "Verzögerung": "Delay",
  "Weitere PCs verbindest du am besten über die Webseite (github.io) – hier ist die App fest mit diesem PC verbunden.": "Connect further PCs via the website (github.io) – here the app is tied to this PC.",
  "Weiteren PC hinzufügen": "Add another PC",
  "Wiederherstellungspunkt angelegt": "Restore point created",
  "Wiederherstellungspunkte": "Restore points",
