  "{n} von 5 Sternen": "{n} of 5 stars",
  "{s} Sekunden": "{s} seconds",
  "„{n}“ wird von diesem Gerät entfernt. Zum erneuten Verbinden musst du neu koppeln.": "“{n}” is removed from this device. To connect again you have to pair again.",
  "Automatisch (wöchentlich)": "Automatic (weekly)",
  "Vor einem Update": "Before an update",
  "Vor einer Wiederherstellung": "Before a restore",
  "Manuell": "Manual",
  "Export": "Export",
  "60-%-Tastaturen (z. B. Royal Kludge): F-Tasten über Fn + Zahl drücken – die App erkennt dann F1 … F12. Besonders gut: in der Tastatur-Software eine Taste auf F13–F24 legen; die nutzt kein Spiel.": "60 % keyboards (e.g. Royal Kludge): press F keys via Fn + number – the app then recognises F1 … F12. Even better: map a key to F13–F24 in the keyboard software; no game uses those.",
  "Aktive Sammlung wählen": "Choose active collection",
  "Alles übertragen.": "Everything has been sent.",
  "Anzeigen": "Show",
  "Audio-Einstellungen speichern": "Save audio settings",
  "Auf diesem Gerät sofort nutzbar, auf dem PC nach dem nächsten Verbinden.": "Usable on this device right away, on the PC after the next connection.",
  "Automatischen Profilwechsel ändern": "Change automatic profile switching",
  "Automatisierung löschen": "Delete automation",
  "Automatisierung speichern {n}": "Save automation {n}",
  "Datei ist kein gültiges Plugin-Paket (kein ZIP).": "File is not a valid plugin package (not a ZIP).",
  "Der PC ist verbunden.": "The PC is connected.",
  "Die vorgemerkte Plugin-Datei ist auf diesem Gerät nicht mehr vorhanden.": "The queued plugin file is no longer on this device.",
  "Diese Kombination ist schon einem anderen Hotkey zugeordnet.": "This combination is already assigned to another hotkey.",
  "Dieser Browser kann Plugin-Pakete nicht entpacken – bitte aktualisieren oder am PC installieren.": "This browser cannot unpack plugin packages – please update it or install on the PC.",
  "Du kannst schon alles einrichten – Spiele bearbeiten, Sounds, Profile, Hotkeys, Aktionen, Automatisierungen, Plugins, Design. Übertragen wird beim ersten Verbinden.": "You can already set everything up – edit games, sounds, profiles, hotkeys, actions, automations, plugins, design. It is sent when you first connect.",
  "Einige Änderungen hat der PC abgelehnt – bitte ansehen.": "The PC refused some changes – please have a look.",
  "Einstellungen speichern": "Save settings",
  "Gaming-Maus (z. B. Attack Shark): Seitentasten hier im Feld drücken oder oben wählen. Solange der Hotkey aktiv ist, löst die Taste nur die Aktion aus (nicht mehr „Zurück“ im Browser). Alternativ in der Maus-Software die Seitentaste auf F13–F24 legen.": "Gaming mouse (e.g. Attack Shark): press the side buttons in this field or pick them above. While the hotkey is active, the button only triggers the action (no longer “Back” in the browser). Alternatively map the side button to F13–F24 in the mouse software.",
  "Hotkey löschen": "Delete hotkey",
  "Hotkey speichern {n}": "Save hotkey {n}",
  "Jetzt übertragen": "Send now",
  "Notiz zur Spielsitzung": "Note for a game session",
  "Ohne PC: Der Store kommt direkt von der Projekt-Webseite (Signatur hier geprüft). Plugins werden heruntergeladen und geprüft, sind auf diesem Gerät sofort nutzbar und werden beim nächsten Verbinden auf dem PC installiert.": "Without a PC: the store comes directly from the project website (signature checked here). Plugins are downloaded and checked, usable on this device right away and installed on the PC at the next connection.",
  "PC nicht verbunden: Du kannst trotzdem Plugins installieren, aktivieren und einstellen. Designs und Widgets gehen sofort auf diesem Gerät; auf den PC kommt alles beim nächsten Verbinden.": "PC not connected: you can still install, enable and configure plugins. Designs and widgets work on this device right away; everything reaches the PC at the next connection.",
  "Paket enthält mehr als 100 Dateien.": "Package contains more than 100 files.",
  "Paket stimmt nicht mit dem Katalog überein (Größe/Prüfsumme) – nicht übernommen.": "Package does not match the catalog (size/checksum) – not taken over.",
  "Paketinhalt passt nicht zum Katalogeintrag – nicht übernommen.": "Package content does not match the catalog entry – not taken over.",
