  "Plugin-Einstellungen speichern": "Save plugin settings",
  "Plugin-Katalog nicht erreichbar (HTTP {s}).": "Plugin catalog not reachable (HTTP {s}).",
  "Plugin-Optionen ändern": "Change plugin options",
