  "Startmenü, Sperrbildschirm und die Windows-Widget-Leiste (Win+W) lassen normale Programme nicht zu – dafür gibt es deshalb keinen Knopf.": "The Start menu, lock screen and the Windows widget board (Win+W) do not allow normal programs – so there is no button for them.",
