  "Dashboard": "Dashboard",
  "Die Datei wurde auf dem PC gelöscht oder verschoben. Diese Sounds sind gestrichelt markiert – neu importieren oder löschen.": "The file was deleted or moved on the PC. These sounds have a dashed outline – import them again or delete them.",
  "Dieses Gerät → PC": "This device → PC",
  "Eigene Ping-Ziele speichern": "Save own ping targets",
  "Eigene Ziele (z. B. Spiel-Server)": "Own targets (e.g. game server)",
  "Ein Spiel-Server lässt sich nur messen, wenn du seine Adresse kennst – z. B. aus den Server-Infos im Spiel. Ohne Adresse misst die App bewusst keinen „Spiel-Ping“. Manche Server beantworten keinen Ping; dann zeigt die App Verlust, obwohl das Spiel läuft.": "A game server can only be measured if you know its address – e.g. from the server info in the game. Without an address the app deliberately measures no “game ping”. Some servers do not answer pings; then the app shows loss although the game works.",
  "Einstell.": "Settings",
  "Erlaubt sind nur die Aktionen dieser Liste. Makros, die in Online-Spielen Eingaben automatisieren (z. B. Tasten spammen, automatisch bauen oder Waffen wechseln), gibt es bewusst nicht – sie verstoßen gegen die Regeln der meisten Spiele und können zu Sperren führen.": "Only the actions in this list are allowed. Macros that automate input in online games (e.g. spamming keys, auto-building or switching weapons) are deliberately not available – they break the rules of most games and can lead to bans.",
  "Erste Messwerte kommen in wenigen Sekunden …": "First values arrive in a few seconds …",
  "Faustregeln für Online-Spiele, aus den Werten der letzten Minuten. Eine Garantie für ein bestimmtes Spiel ist das nicht.": "Rules of thumb for online games, from the values of the last minutes. It is no guarantee for a particular game.",
  "Gemessen wird auf dem PC – ohne Verbindung gibt es keine Messwerte. Eigene Ziele kannst du schon eintragen.": "Measured on the PC – without a connection there are no values. You can already add own targets.",
  "Globale Tastenkombinationen auf dem PC – funktionieren auch, während ein Spiel im Vordergrund ist. Für Abfolgen mehrerer Schritte eine Quick Action anlegen und hier zuweisen.": "Global key combinations on the PC – they also work while a game is in the foreground. For sequences of several steps create a quick action and assign it here.",
