  "Ping, Schwankung (Jitter) und Paketverlust – gemessen vom PC aus, alle 2 Sekunden, nur solange diese Seite offen ist.": "Ping, variation (jitter) and packet loss – measured from the PC every 2 seconds, only while this page is open.",
