  "Qualität": "Quality",
  "Reihenfolge innerhalb der Kategorien ändern und selten genutzte Bereiche ausblenden. Ausgeblendete Bereiche bleiben über die Suche erreichbar. Home, Einstellungen und PC verbinden lassen sich nicht ausblenden.": "Change the order within the categories and hide sections you rarely use. Hidden sections stay reachable through the search. Home, Settings and Connect PC cannot be hidden.",
  "Router: Verbindung im Heimnetz (WLAN/Kabel). Internet: Cloudflare und Google als Referenz. Viele Router beantworten keinen Ping – dann zählt das als Verlust, obwohl das Internet geht.": "Router: connection in the home network (Wi-Fi/cable). Internet: Cloudflare and Google as reference. Many routers do not answer pings – then this counts as loss although the internet works.",
