  "Bringt neue Plugin-Dateien oder Rechte auf den PC – erst nach Bestätigung": "Brings new plugin files or rights to the PC – only after confirmation",
  "Einige Änderungen (Plugins oder ältere) werden erst nach deiner Bestätigung übertragen.": "Some changes (plugins or older ones) are only transferred after your confirmation.",
  "GitHub Pages: Update-Prüfung und Plugin-Katalog (täglich, nicht während eines Spiels) – sieht die IP-Adresse des PCs.": "GitHub Pages: update check and plugin catalog (daily, not during a game) – sees the PC's IP address.",
  "Keine Telemetrie, keine Werbung, kein Konto.": "No telemetry, no ads, no account.",
  "Netzwerkdiagnose: Ping an Cloudflare (1.1.1.1), Google (8.8.8.8) und deine eigenen Ziele – nur solange die Seite offen ist.": "Network diagnosis: ping to Cloudflare (1.1.1.1), Google (8.8.8.8) and your own targets – only while the page is open.",
  "Neu laden, um sie zu verwenden. Nicht gespeicherte Eingaben auf dieser Seite gehen dabei verloren.": "Reload to use it. Unsaved input on this page will be lost.",
