  "Steam / Microsoft Store: Cover-Suche (Spielname), Steam-CDN für Bilder (IP-Adresse), Steam Web API mit deinem Schlüssel, Game-Pass-Katalog.": "Steam / Microsoft Store: cover search (game name), Steam CDN for images (IP address), Steam Web API with your key, Game Pass catalog.",
