  "Auf der Liste": "On the list",
  "Aus = keine einzige Anfrage. An = der PC fragt höchstens alle {h} Stunden (nie während eines Spiels) bei store.steampowered.com nach – Steam sieht dabei die IP-Adresse des PCs und die App-IDs.": "Off = not a single request. On = the PC asks store.steampowered.com at most every {h} hours (never during a game) – Steam sees the PC's IP address and the app IDs.",
  "Aus der Spielerkennung auf dem PC (Gaming-Verlauf)": "From the game detection on the PC (gaming history)",
