  "Die Suche fragt den Steam-Shop – dafür oben die Preisabfrage einschalten. Von Hand eintragen geht immer.": "Search asks the Steam store – switch on price checks above first. Adding by hand always works.",
  "Die Suche läuft über den PC – ohne Verbindung nur von Hand eintragen.": "Search runs via the PC – without a connection you can only add by hand.",
  "Die Wunschliste ist leer": "The wish list is empty",
