  "Quelle: {s}. Das ist der öffentliche Endpunkt des Steam-Webshops, keine offizielle Preis-API – er kann sich ändern. Verlauf = nur Preise, die dieser PC selbst gesehen hat.": "Source: {s}. This is the public endpoint of the Steam web store, not an official price API – it may change. History = only prices this PC has seen itself.",
