  "Woche beginnt am Montag (Zeitzone des PCs).": "The week starts on Monday (PC time zone).",
  "Wunschliste": "Wish list",
  "Wunschliste mit Zielpreis. Der PC prüft die Preise im Steam-Shop und meldet sich, wenn ein Spiel dein Ziel erreicht.": "Wish list with target prices. The PC checks prices in the Steam store and tells you when a game reaches your target.",
