  "Priorität von {n}": "Priority of {n}",
  "Querformat": "Landscape",
  "Solange das Profil aktiv ist (z. B. automatisch beim Start eines zugeordneten Spiels), zeigen PC, Handy und iPad diese Farben. Danach kommt das eigene Design zurück. Auf jedem Gerät abschaltbar unter Einstellungen → Design.": "While the profile is active (e.g. automatically when an assigned game starts), PC, phone and iPad show these colours. Afterwards the own design returns. Can be switched off on each device under Settings → Design.",
  "Spiele suchen": "Search games",
  "Spiele zum Backlog hinzufügen": "Add games to the backlog",
  "Spiele, die du noch nicht besitzt, stehen auf der Wunschliste im Deal Radar (mit Zielpreis).": "Games you don't own yet go on the wishlist in Deal Radar (with target price).",
  "Spielzeit, Sitzungen, Spiele, Tage": "Play time, sessions, games, days",
  "Statistik-Karte": "Stats card",
  "Status": "Status",
  "Status von {n}": "Status of {n}",
  "Suchen (Name, Notiz)": "Search (name, note)",
  "Tabelle (CSV)": "Spreadsheet (CSV)",
  "Tage gespielt": "Days played",
  "Theme": "Theme",
  "Themes der Gaming-Profile anzeigen": "Show themes of gaming profiles",
  "Titel": "Title",
  "Unter 1 Stunde": "Under 1 hour",
  "Vergleich mit dem vorherigen Zeitraum": "Comparison with the previous period",
  "Vorheriger Zeitraum: keine Spielzeit erfasst": "Previous period: no play time recorded",
  "Vorschau der Statistik-Karte": "Preview of the stats card",
  "Was du noch spielen willst, gerade spielst oder durchgespielt hast. Den Status setzt nur du – nichts wird automatisch als durchgespielt markiert. Spielzeit kommt aus dem Gaming-Verlauf.": "What you still want to play, are playing or have completed. Only you set the status – nothing is marked as completed automatically. Play time comes from the gaming history.",
  "Wunschliste, Export und Import": "Wishlist, export and import",
  "Ziel h": "Goal h",
