  "Ein Deck ist ein Raster großer Tasten zum Antippen – wie ein Stream Deck auf dem Handy: Spiele starten, Sounds, Profile, Lautstärke, Ordner. Erstellen geht auch ohne PC; gespeichert wird es auf dem PC, gleich auf allen Geräten.": "A deck is a grid of big keys to tap – like a Stream Deck on your phone: start games, sounds, profiles, volume, folders. Works without the PC too; it is stored on the PC, the same on all devices.",
