  "Screenshots und Clips vom PC – nach Spiel, Tag oder Ordner. Bereits angesehene Vorschaubilder bleiben auf dem Gerät, Favoriten und Schlagwörter gehen auch ohne PC.": "Screenshots and clips from the PC – by game, day or folder. Thumbnails you have seen stay on the device; favorites and tags work without the PC too.",
