  "Speicher": "Storage",
  "Speicher & Updates": "Storage & updates",
  "Steam meldet Größe und Update-Stand selbst; andere Größen werden nur auf Anfrage berechnet. * = einige Ordner waren nicht lesbar. Aktualisieren, Löschen und Deinstallieren im jeweiligen Launcher.": "Steam reports size and update state itself; other sizes are only computed on request. * = some folders were not readable. Update, delete and uninstall in the respective launcher.",
