  "Anforderungen vom Steam-Shop, Stand {d}.": "Requirements from the Steam store, as of {d}.",
  "Auf iPhone und iPad erlaubt Apple Push nur für Apps auf dem Home-Bildschirm: Teilen → „Zum Home-Bildschirm“, dann von dort öffnen (ab iOS 16.4).": "On iPhone and iPad, Apple only allows push for apps on the home screen: Share → \"Add to Home Screen\", then open it from there (iOS 16.4 or later).",
