  "Auswahl speichern": "Save selection",
  "Bedingung nicht erfüllt": "condition not met",
  "Benachrichtigungen sind für diese Seite im Browser blockiert – in den Website-Einstellungen erlauben.": "Notifications are blocked for this site in the browser – allow them in the site settings.",
  "Benachrichtigungen wurden nicht erlaubt.": "Notifications were not allowed.",
  "Braucht den PC: er fragt einmal den Steam-Shop nach den Anforderungen und vergleicht mit deiner Hardware.": "Needs the PC: it asks the Steam store once for the requirements and compares them with your hardware.",
  "Dein PC: {c} · {g} · {r} GB RAM": "Your PC: {c} · {g} · {r} GB RAM",
  "Dieser Browser unterstützt keine Hintergrund-Dienste (Service Worker).": "This browser does not support background services (service workers).",
  "Dieser Browser unterstützt keine Push-Benachrichtigungen.": "This browser does not support push notifications.",
  "Einschalten braucht einmal die Verbindung zum PC – danach kommen Meldungen auch ohne offene App.": "Turning it on needs the PC connection once – after that messages arrive even without the app open.",
  "Empfohlen": "Recommended",
  "Erfüllt die Mindestanforderungen (soweit prüfbar), nicht alle empfohlenen": "Meets the minimum requirements (as far as checkable), not all recommended ones",
