  "Nicht automatisch prüfbar – bitte die Angaben vergleichen": "Cannot be checked automatically – please compare the details",
  "Profil zurücksetzen": "Restore profile",
  "Prozessor unbekannt": "Processor unknown",
  "Prozessor und Grafikkarte bitte selbst vergleichen – ihre Namen lassen sich nicht zuverlässig automatisch einstufen.": "Please compare processor and graphics card yourself – their names cannot be ranked reliably automatically.",
  "Push auf diesem Gerät": "Push on this device",
  "Push einschalten": "Turn on push",
  "Push ist auf diesem Gerät an": "Push is on for this device",
  "Schon erledigte Schritte bleiben erledigt (z. B. gestartete Programme).": "Steps already done stay done (e.g. started programs).",
  "Test gesendet – kommt gleich als Benachrichtigung": "Test sent – arrives shortly as a notification",
  "Test senden": "Send test",
  "Unter den Mindestanforderungen": "Below the minimum requirements",
  "Vorheriges Profil wieder aktiv": "Previous profile active again",
  "Wichtige Meldungen vom PC kommen auch bei geschlossener App – z. B. Termin-Erinnerungen oder ein fertiger Ablauf. Der PC verschlüsselt jede Nachricht; der Push-Dienst des Browsers (Google, Apple, Mozilla, Microsoft) leitet nur weiter.": "Important messages from the PC arrive even while the app is closed – e.g. event reminders or a finished scene. The PC encrypts every message; the browser's push service (Google, Apple, Mozilla, Microsoft) only forwards it.",
  "Zuletzt gesendet: {d}": "Last sent: {d}",
  "abgebrochen": "cancelled",
  "fertig": "done",
  "mit Fehlern": "with errors",
  "„{n}“ läuft – Fortschritt und Abbrechen unter Quick Actions": "\"{n}\" is running – progress and cancel under Quick Actions",
  "Fortschritt": "Progress",
  "Erfüllt die Mindestanforderungen (soweit prüfbar) – Steam nennt keine empfohlenen": "Meets the minimum requirements (as far as checkable) – Steam names no recommended ones",
  "Daten (Bibliothek, Profile, Kopplungen …) liegen getrennt und bleiben bei Updates und beim Deinstallieren erhalten. Ohne Code-Signatur zeigt Windows beim ersten Start evtl. „Der Computer wurde durch Windows geschützt“ → „Weitere Informationen“ → „Trotzdem ausführen“.": "Data (library, profiles, pairings …) is kept separately and stays through updates and uninstalling. Without code signing, Windows may show \"Windows protected your PC\" on the first start → \"More info\" → \"Run anyway\".",
  "Deinstallieren": "Uninstall",
  "Eintrag im Startmenü": "Start menu entry",
  "Es ist schon eine Version installiert, diese hier läuft aber von einem anderen Ort. „Installieren“ ersetzt die installierte durch diese.": "A version is already installed, but this one runs from another place. \"Install\" replaces the installed one with this one.",
  "Installation": "Installation",
  "Installation & Autostart": "Installation & autostart",
  "Installieren gibt es nur im Windows-Begleiter.": "Installing is only available in the Windows companion.",
  "Installiert für dein Benutzerkonto – in „Apps & Features“ als „Nexus Gaming Hub“.": "Installed for your user account – in \"Apps & features\" as \"Nexus Gaming Hub\".",
  "Installiert – das Programm startet jetzt aus dem neuen Ordner neu": "Installed – the program now restarts from its new folder",
  "Läuft gerade direkt aus der heruntergeladenen Datei. Installieren legt das Programm in einen eigenen Ordner, ins Startmenü und in „Apps & Features“ (mit Deinstallieren) – ohne Administrator.": "Currently runs straight from the downloaded file. Installing puts the program into its own folder, the Start menu and \"Apps & features\" (with uninstall) – no administrator needed.",
  "Nexus Gaming Hub deinstallieren?": "Uninstall Nexus Gaming Hub?",
  "Ordner: {p}": "Folder: {p}",
  "Startmenü-Eintrag, Desktop-Symbol, Autostart und das Programm werden entfernt. Deine Einstellungen und Daten bleiben (für eine spätere Installation).": "Start menu entry, desktop icon, autostart and the program are removed. Your settings and data stay (for a later installation).",
