  "Lege die Mod als ZIP in den Austausch-Ordner – am Handy unter": "Put the mod as a ZIP into the exchange folder – on the phone under",
  "Linker Stick": "Left stick",
  "Läuft über das kostenlose OpenRGB (openrgb.org), das Tastatur, Maus, RAM, Mainboard und Lüfter vieler Hersteller steuert. In OpenRGB unter „SDK Server“ auf „Start Server“ tippen (am besten „Start at login“ und „Start Server“ in den Einstellungen anhaken).": "Works through the free OpenRGB (openrgb.org), which controls keyboard, mouse, RAM, mainboard and fans of many makers. In OpenRGB, tap \"Start Server\" under \"SDK Server\" (best tick \"Start at login\" and \"Start Server\" in the settings).",
  "Maximiert": "Maximized",
  "Minimiert": "Minimized",
  "Mod entfernen?": "Remove mod?",
  "Mod-Ordner": "Mods folder",
  "Mod-Ordner einstellen": "Set mods folder",
  "Mod-Ordner gespeichert": "Mods folder saved",
  "Mods": "Mods",
  "Mods eines Spiels an- und ausschalten, aus einer ZIP-Datei installieren und entfernen. Vor jeder Änderung sichert der PC den Mod-Ordner – du kannst jederzeit zurück.": "Switch a game's mods on and off, install from a ZIP file and remove them. Before every change the PC saves the mods folder – you can always go back.",
  "Mods gehen für Spiele, deren Ordner der PC kennt (Steam, Epic, eigene Spiele mit Ordner).": "Mods work for games whose folder the PC knows (Steam, Epic, own games with a folder).",
