  "Noch keine – sie entstehen automatisch vor dem Installieren, Entfernen und Zurückholen (die letzten 5 bleiben).": "None yet – they are created automatically before installing, removing and restoring (the last 5 are kept).",
  "Nur dieser PC (127.0.0.1) oder ein Gerät im Heimnetz – OpenRGB hat kein Passwort.": "Only this PC (127.0.0.1) or a device in the home network – OpenRGB has no password.",
  "Ohne PC: Layouts umbenennen und löschen geht (wird übertragen); anwenden und neu erstellen braucht den PC.": "Without the PC: renaming and deleting layouts works (sent later); applying and creating needs the PC.",
  "Ohne PC: Stand vom {d}. Ändern geht erst mit dem PC.": "Without PC: state from {d}. Changing needs the PC.",
  "OpenRGB ist verbunden, findet aber keine Geräte.": "OpenRGB is connected but finds no devices.",
  "Ordne deine Fenster am PC an und tippe auf „Aus offenen Fenstern“.": "Arrange your windows on the PC and tap \"From open windows\".",
  "Ordner ändern": "Change folder",
  "Profil „{n}“ geladen": "Profile \"{n}\" loaded",
  "Profile:": "Profiles:",
  "Prüfe deinen Controller (Tasten, Sticks, Vibration, Akku) und steuere die RGB-Beleuchtung über OpenRGB – auch als Baustein in Quick Actions.": "Check your controller (buttons, sticks, vibration, battery) and control RGB lighting through OpenRGB – also as a building block in quick actions.",
  "RGB-Beleuchtung (OpenRGB)": "RGB lighting (OpenRGB)",
  "RGB-Farbe setzen (OpenRGB)": "Set RGB color (OpenRGB)",
  "RGB-Profil laden (OpenRGB)": "Load RGB profile (OpenRGB)",
  "Rechter Stick": "Right stick",
  "Sicherung zurückgeholt": "Backup restored",
  "Sicherung zurückholen?": "Restore backup?",
  "Sicherungen ({n})": "Backups ({n})",
  "Speichere, wo deine Programme liegen – z. B. Discord und Spotify auf dem zweiten Monitor, OBS maximiert – und stell es mit einem Tipp wieder her. Auch als Baustein in Quick Actions.": "Save where your programs sit – e.g. Discord and Spotify on the second monitor, OBS maximized – and restore it with one tap. Also as a building block in quick actions.",
  "Sticks: kleine Ausschläge (unter 8 %) werden als Ruhe angezeigt – wandert der Punkt ohne Berührung, driftet der Stick.": "Sticks: small movements (under 8 %) are shown as rest – if the dot wanders without touching, the stick drifts.",
  "Test beenden": "End test",
  "Umbenennen": "Rename",
  "Unterordner im Spiel, in dem die Mods liegen – z. B. „Mods“ (Stardew Valley, The Sims), „BepInEx/plugins“ (Unity-Spiele) oder „Content/Paks/~mods“ (Unreal).": "Subfolder of the game that holds the mods – e.g. \"Mods\" (Stardew Valley, The Sims), \"BepInEx/plugins\" (Unity games) or \"Content/Paks/~mods\" (Unreal).",
  "Verbindung zu OpenRGB": "Connection to OpenRGB",
  "Verschoben werden nur Fenster, die gerade offen sind – Programme werden nicht gestartet. Fehlt ein Monitor, landet das Fenster auf dem Hauptmonitor. Programme mit Administratorrechten lassen sich von Windows aus nicht verschieben.": "Only windows that are open are moved – programs are not started. If a monitor is missing, the window goes to the main monitor. Programs running with administrator rights cannot be moved by Windows.",
  "Vibrieren": "Vibrate",
  "Vorher sichert der PC den Mod-Ordner.": "The PC saves the mods folder first.",
  "Zurückholen": "Restore",
  "senden oder am PC hineinkopieren.": "send it, or copy it in on the PC.",
  "z. B. Streamen": "e.g. Streaming",
  "{n} Dateien ({s}), nichts wird überschrieben.": "{n} files ({s}), nothing is overwritten.",
  "{n} Dateien ({s}). Diese werden überschrieben: {o}": "{n} files ({s}). These are overwritten: {o}",
