  "{n} von {m} Fenstern an ihrem Platz": "{n} of {m} windows in place",
  "„{n}“ wird gelöscht. Vorher sichert der PC den Mod-Ordner.": "\"{n}\" is deleted. The PC saves the mods folder first.",
  "„{z}“ installieren?": "Install \"{z}\"?",
  "Auch im Microsoft Store (Xbox) vergleichen": "Also compare in the Microsoft Store (Xbox)",
  "Bei jeder Prüfung abgeglichen. Deine Steam-Wunschliste muss öffentlich sein (Steam → Profil → Privatsphäre → Spieldetails).": "Synced at every check. Your Steam wishlist must be public (Steam → Profile → Privacy → Game details).",
  "Dafür unter Spiele → Steam die Bibliothek verbinden oder am PC bei Steam angemeldet sein.": "For this, connect the library under Games → Steam or be signed in to Steam on the PC.",
  "Deal-Radar-Einstellungen ändern": "Change Deal Radar settings",
  "Der Name reicht: der PC findet das Spiel im Steam-Shop (und im Microsoft Store, falls eingeschaltet) und vergleicht die Preise.": "The name is enough: the PC finds the game in the Steam store (and in the Microsoft Store, if switched on) and compares the prices.",
  "Die Preisabfrage ist aus – der Name wird gespeichert, gesucht wird nach dem Einschalten.": "Price checks are off – the name is saved and searched once you switch them on.",
  "Fragt zusätzlich displaycatalog.mp.microsoft.com – den Katalog, aus dem auch die Xbox-App ihre Preise zeigt. Gezeigt wird die günstigste kaufbare Edition mit passendem Namen.": "Also asks displaycatalog.mp.microsoft.com – the catalog the Xbox app takes its prices from. Shows the cheapest buyable edition with a matching name.",
  "Genauer suchen": "Search more precisely",
  "Im Microsoft Store öffnen": "Open in the Microsoft Store",
  "Jetzt holen": "Fetch now",
  "Microsoft Store (Xbox):": "Microsoft Store (Xbox):",
  "Name des Spiels, z. B. Hades II": "Name of the game, e.g. Hades II",
  "Noch keinem Steam-Spiel zugeordnet – der PC sucht es bei der nächsten Prüfung über den Namen.": "Not matched to a Steam game yet – the PC looks it up by name at the next check.",
  "Ohne PC prüft das Handy den Preis gleich selbst: Xbox im Microsoft Store, Steam in der Preisliste der Website. Findet es das Spiel nicht, sucht der PC beim Verbinden.": "Without the PC the phone checks the price itself right away: Xbox at the Microsoft Store, Steam in the price list on the website. If it cannot find the game, the PC looks it up when it connects.",
  "Kein Preis gefunden – der PC sucht das Spiel beim Verbinden.": "No price found – the PC looks the game up when it connects.",
  "Geprüft: {p}": "Checked: {p}",
  "Steam günstiger": "Steam cheaper",
