  "Tippe oben einfach den Namen eines Spiels ein – oder lass deine Steam-Wunschliste übernehmen.": "Just type the name of a game above – or let your Steam wishlist be imported.",
  "Wunschliste abgeglichen {d}": "Wishlist synced {d}",
  "Wunschliste mit Zielpreis. Der PC prüft die Preise im Steam-Shop und im Microsoft Store (Xbox), übernimmt deine Steam-Wunschliste und meldet sich, wenn ein Spiel dein Ziel erreicht.": "Wishlist with target prices. The PC checks prices in the Steam store and the Microsoft Store (Xbox), imports your Steam wishlist and tells you when a game reaches your target.",
