  "Belegungen ({n})": "Mappings ({n})",
  "Buchstaben": "Letters",
  "Controller-Tasten lassen sich nur mit einem virtuellen Controller-Treiber umlegen – das macht Steam Input für jedes Spiel (Steam → Spiel → Controller-Layout). Testen kannst du deinen Controller unter": "Controller buttons can only be remapped with a virtual controller driver – Steam Input does that for every game (Steam → game → controller layout). You can test your controller under",
  "Dazu gedrückt halten:": "Hold together with:",
  "Die Belegung wirkt nur mit dem Windows-Begleiter. Profile kannst du hier trotzdem vorbereiten.": "Remapping only works with the Windows companion. You can still prepare profiles here.",
  "Die linke Maustaste lässt sich nicht umlegen – sonst kommst du nicht mehr an die Einstellungen.": "The left mouse button cannot be remapped – otherwise you could no longer reach the settings.",
  "Diese Taste kennt die App nicht.": "The app doesn't know this key.",
  "Ergebnis: {d}": "Result: {d}",
  "Erkannte Geräte": "Detected devices",
  "Funktionstasten": "Function keys",
  "Gespeichert – gilt sofort": "Saved – applies right away",
  "Gilt für": "Applies to",
  "Gut zu wissen: Die Belegung gilt für alle angeschlossenen Tastaturen und Mäuse gleichzeitig – Windows sagt dabei nicht, von welchem Gerät ein Tastendruck kommt. Spiele, die als Administrator laufen, sehen umgelegte Tasten nur, wenn der Begleiter auch als Administrator läuft. Manche Spiele mit Anti-Cheat ignorieren umgelegte Tasten. Makros (mehrere Tasten nacheinander, Wiederholungen) gibt es bewusst nicht.": "Good to know: mappings apply to all connected keyboards and mice at once – Windows doesn't say which device a key press comes from. Games running as administrator only see remapped keys if the companion runs as administrator too. Some games with anti-cheat ignore remapped keys. Macros (several keys in a row, repeats) are deliberately not possible.",
  "Höchstens {n} Belegungen pro Profil.": "At most {n} mappings per profile.",
  "Jetzt Taste am PC drücken …": "Press a key on the PC now …",
  "Kein Profil eingeschaltet": "No profile switched on",
  "Keine Tastatur oder Maus gefunden.": "No keyboard or mouse found.",
  "Kontextmenü-Taste": "Menu key",
  "Leertaste": "Space",
  "Leg Tasten und Maustasten am PC um – überall oder nur in bestimmten Spielen. Eine Taste wird zu einer anderen Taste, einer Tastenkombination, einer Maustaste oder wird gesperrt.": "Remap keys and mouse buttons on the PC – everywhere or only in certain games. A key becomes another key, a shortcut, a mouse button or is blocked.",
  "Linke Maustaste": "Left mouse button",
  "Maus": "Mouse",
  "Medien": "Media",
  "Mittlere Maustaste (Rad)": "Middle mouse button (wheel)",
  "Noch keine Belegung": "No mappings yet",
  "Noch keine – tippe oben eine Taste an.": "None yet – tap a key above.",
  "Notaus am PC: Strg + Alt + F12 schaltet alle Belegungen sofort aus und wieder an.": "Emergency stop on the PC: Ctrl + Alt + F12 switches all mappings off and on again right away.",
  "Nur in: {p}": "Only in: {p}",
  "Pausieren": "Pause",
  "Pausiert – alle Tasten sind wieder normal": "Paused – all keys are back to normal",
  "Programmname": "Program name",
  "Programmname, z. B. cs2": "Program name, e.g. cs2",
  "Rechte Maustaste": "Right mouse button",
  "Royal Kludge und Attack Shark erkennt die App am Gerätenamen. Die Belegung funktioniert aber mit jedem Gerät. Was die Hersteller-Software direkt im Gerät speichert (z. B. Fn-Ebenen, DPI), bleibt davon unberührt.": "The app recognizes Royal Kludge and Attack Shark by the device name. Remapping works with every device, though. What the maker's software stores in the device itself (e.g. Fn layers, DPI) stays untouched.",
