  "Zum Beispiel: Caps Lock wird Strg, die Windows-Taste ist im Spiel gesperrt, die Seitentaste der Maus wird zu Push-to-Talk.": "For example: Caps Lock becomes Ctrl, the Windows key is blocked in the game, the mouse side button becomes push-to-talk.",
