  "Am langsamsten": "Slowest",
  "Am schnellsten": "Fastest",
  "Die letzten Starts waren deutlich langsamer als vorher. Häufige Gründe: ein Update wird beim Start geprüft, Shader werden neu erstellt oder der Launcher musste erst selbst starten.": "The last starts were clearly slower than before. Common reasons: an update is checked at start, shaders are rebuilt or the launcher had to start first.",
  "Die letzten Starts waren deutlich schneller als vorher.": "The last starts were clearly faster than before.",
  "Einzelne Starts dauern viel länger als üblich – oft der erste Start nach einem Update oder Neustart des PCs.": "Some starts take much longer than usual – often the first start after an update or a PC restart.",
  "Gemessen wird bis das Programm des Spiels läuft – nicht bis zum Hauptmenü. Gezählt werden nur Starts aus der App, bei denen das Spiel innerhalb von {m} Minuten erkannt wurde. Nach einem Start sucht der PC 3 Minuten lang jede Sekunde nach dem Spiel, dadurch ist die Messung auf etwa eine Sekunde genau.": "Measured until the game's program is running – not until the main menu. Only starts from the app count where the game was detected within {m} minutes. After a start the PC looks for the game every second for 3 minutes, so the measurement is accurate to about one second.",
  "Letzte Starts": "Recent starts",
  "Letzter Start {d}": "Last start {d}",
  "Noch keine Messung": "No measurement yet",
  "Ohne PC: zuletzt geladener Stand.": "Without the PC: last loaded state.",
  "Starte ein Spiel aus der App – sobald sein Programm läuft, steht hier die Zeit. Spiele brauchen dafür eine Erkennung (Prozessname oder Installationsordner).": "Start a game from the app – as soon as its program runs, the time shows up here. Games need detection for this (process name or install folder).",
  "Startzeit": "Start time",
  "Startzeit-Analyse": "Start-time analysis",
  "Wie lange dauert es vom Tippen auf „Spielen“, bis das Spiel am PC läuft? Gemessen wird bei jedem Start aus der App – je Spiel mit Verlauf.": "How long does it take from tapping \"Play\" until the game runs on the PC? Measured at every start from the app – per game with history.",
