  "Obere Hälfte": "Top half",
  "Ohne PC: Layouts mit „Neues Layout“ anlegen, bearbeiten und löschen geht (wird übertragen); anwenden braucht den PC.": "Without the PC: creating layouts with \"New layout\", editing and deleting works (sent later); applying needs the PC.",
  "Ohne PC: Xbox-Preise prüft das Handy selbst (zuletzt {d}). Steam-Preise sind vom letzten Abgleich am PC.": "Without the PC: the phone checks Xbox prices itself (last {d}). Steam prices are from the PC's last check.",
  "Ohne PC: das Handy kann die Xbox-Preise selbst beim Microsoft Store prüfen. Steam-Preise kommen vom PC.": "Without the PC: the phone can check Xbox prices itself at the Microsoft Store. Steam prices come from the PC.",
  "Optional: Mit Benutzername und Passwort nimmst du dein Design (Farben, Hintergrund, Startseite, untere Leiste, Sprache) in einen neuen Browser mit. Das Design wird schon im Browser verschlüsselt und auf deinem PC gespeichert – der PC kann es nicht lesen, das Passwort verlässt dein Gerät nie.": "Optional: with a user name and password you take your design (colors, background, home screen, bottom bar, language) to a new browser. The design is encrypted in the browser and stored on your PC – the PC cannot read it, the password never leaves your device.",
  "Passwort": "Password",
