  "Stand vom letzten Verbinden": "As of the last connection",
  "Tippe auf „Neues Layout“ und wähle für jedes Programm einen Platz – z. B. Discord links auf dem zweiten Monitor. Oder ordne die Fenster am PC an und nimm „Aus offenen Fenstern“.": "Tap \"New layout\" and choose a position for each program – e.g. Discord on the left of the second monitor. Or arrange the windows on the PC and use \"From open windows\".",
