  "Angemeldet – deine Daten sind geladen": "Signed in – your data is loaded",
  "Anmelden (optional)": "Sign in (optional)",
  "Anmelden oder registrieren": "Sign in or register",
  "Braucht einmal die Verbindung zu deinem PC – dort liegt das Konto (es gibt keinen fremden Server). Ohne PC: Design-Code unten.": "Needs the connection to your PC once – the account is stored there (there is no third-party server). Without the PC: design code below.",
  "Das Konto „{u}“ wird vom PC gelöscht. Die Daten auf diesem Gerät bleiben.": "The account \"{u}\" is deleted from the PC. The data on this device stays.",
  "Daten im Konto gespeichert": "Data saved to the account",
  "Konto": "Account",
  "Konto angelegt – deine Daten sind gespeichert": "Account created – your data is saved",
  "Konto anlegen": "Create account",
  "Konto gelöscht": "Account deleted",
  "Konto löschen": "Delete account",
  "Konto löschen?": "Delete account?",
  "Konto: {u}": "Account: {u}",
  "Optional – ohne E-Mail: Mit Benutzername und Passwort nimmst du deine Daten in einen anderen Browser mit: Design, Startseite und Leiste, Sprache, Gamer-Pass, Zähler und Pausen-Erinnerung. Alles wird schon im Browser verschlüsselt und auf deinem PC gespeichert – der PC kann es nicht lesen, das Passwort verlässt dein Gerät nie. Spiele, Deck, Wunschliste und Kalender liegen ohnehin auf dem PC.": "Optional – no e-mail: with a user name and password you take your data to another browser: design, home screen and bar, language, Gamer Pass, counters and break reminder. Everything is encrypted in the browser and stored on your PC – the PC cannot read it, the password never leaves your device. Games, deck, wishlist and calendar are on the PC anyway.",
  "Registrieren": "Register",
  "Änderungen werden automatisch ins Konto gespeichert, sobald der PC verbunden ist.": "Changes are saved to the account automatically as soon as the PC is connected.",
  "Dein Konto liegt verschlüsselt auf deinem PC – es gibt keinen fremden Server. Verbinde diesen Browser deshalb einmal mit deinem PC, dann kannst du dich registrieren oder anmelden. Ganz ohne PC: Design-Code unten.": "Your account is stored encrypted on your PC – there is no third-party server. So connect this browser to your PC once, then you can register or sign in. Without any PC: design code below.",
  "Animationen sind reduziert – der Ladebildschirm erscheint dann kurz als Standbild.": "Motion is reduced – the loading screen then shows briefly as a still image.",
  "Atmosphären wie Cyberpunk, Space, Ice, Fire oder Glass setzen zusätzlich einen passenden bewegten Hintergrund und Ladebildschirm – alles bleibt unten änderbar. Je Spiel: Theme im Gaming-Profil des Spiels.": "Atmospheres like Cyberpunk, Space, Ice, Fire or Glass also set a matching moving background and loading screen – everything stays changeable below. Per game: theme in the game's gaming profile.",
  "Bewegter Hintergrund": "Moving background",
  "Bild des Spiels zeigen": "Show the game's picture",
  "Dauer: {v} ms": "Duration: {v} ms",
  "Dauer: {v} s": "Duration: {v} s",
  "Deckkraft: {v} %": "Opacity: {v} %",
  "Der Startbefehl geht sofort an den PC – die Animation wartet nie dazwischen. Antippen oder Esc überspringt sie. „Läuft“ steht erst da, wenn der PC das Spiel meldet.": "The start command goes to the PC at once – the animation never waits in between. Tap or Esc skips it. \"Running\" only shows once the PC reports the game.",
  "Effekte zurücksetzen": "Reset effects",
  "Eigener Text (optional)": "Own text (optional)",
  "Gerade als Standbild (Animationen reduziert oder leichte Darstellung).": "Currently a still image (reduced motion or light rendering).",
  "Ladebildschirm beim Spielstart zeigen": "Show a loading screen when a game starts",
  "Läuft auf dem PC": "Running on the PC",
  "Läuft mit höchstens 30 Bildern pro Sekunde und hält an, sobald die Seite nicht sichtbar ist. Bei „Animationen reduzieren“ oder leichter Darstellung bleibt es ein Standbild.": "Runs at most 30 frames per second and stops as soon as the page is not visible. With \"Reduce animations\" or light rendering it stays a still image.",
