  "Der PC geht in den Energiesparmodus.": "The PC goes to sleep.",
  "Der PC geht in den Energiesparmodus. Laufende Downloads und Spiele pausieren.": "The PC goes to sleep. Running downloads and games pause.",
  "Energiesparen, Neustart und Herunterfahren muss der PC für dieses Gerät einmal erlauben: am PC unter Geräte → dieses Gerät → Recht „PC ausschalten“.": "Sleep, restart and shut down must be allowed once for this device on the PC: on the PC under Devices → this device → right \"Switch PC off\".",
