  "PC-Energie": "PC power",
  "Sofort": "Now",
  "Sperren geht sofort. Energiesparen, Neustart und Herunterfahren fragen vorher; Neustart/Herunterfahren nach 60 s, bis dahin abbrechbar. Braucht am PC das Recht „PC ausschalten“ für dieses Gerät.": "Locking is immediate. Sleep, restart and shut down ask first; restart/shut down after 60 s, cancellable until then. Needs the right \"Switch PC off\" for this device on the PC.",
  "Sperren, Neustart und Herunterfahren gehen nur, wenn der PC verbunden ist – sie werden nie für später vorgemerkt.": "Lock, restart and shut down only work while the PC is connected – they are never kept for later.",
  "Wann?": "When?",
  "Was soll passieren?": "What should happen?",
  "Windows zeigt am PC einen Hinweis. Bis dahin kannst du hier (oder auf jedem anderen Gerät) abbrechen.": "Windows shows a notice on the PC. Until then you can cancel here (or on any other device).",
