  "Der Ort existiert gerade nicht (mehr) auf dem PC.": "This place does not exist on the PC right now.",
  "Der jetzige Stand ist schon genau diese Sicherung – nichts zu tun.": "The current state already is exactly this backup – nothing to do.",
