  "Einstellung": "Setting",
  "Eintragen": "Add",
  "Erlaubt: Dokumente, Gespeicherte Spiele, AppData, Steams Cloud-Ordner und Spielordner – keine Browser-, Windows- oder Anmeldedaten. Konfigurationsdateien: ini, cfg, json, xml, txt … bis 2 MB.": "Allowed: Documents, Saved Games, AppData, Steam's cloud folders and game folders – no browser, Windows or credential data. Configuration files: ini, cfg, json, xml, txt … up to 2 MB.",
