  "Ohne PC: Regeln (automatisch sichern, wie viele behalten) kannst du ändern – sie werden beim Verbinden übertragen. Sichern, Prüfen und Zurückholen gehen nur mit dem PC.": "Without the PC: you can change rules (automatic backup, how many to keep) – they are sent when connecting. Backing up, checking and restoring need the PC.",
