  "Sichert Spielstände und Konfigurationsdateien deiner Spiele – mit Prüfsumme, Verlauf und Vorschau vor dem Zurückholen. Gesichert wird auf dem PC; ohne PC kannst du Regeln vorbereiten.": "Backs up savegames and configuration files of your games – with checksums, history and a preview before restoring. Backups happen on the PC; without the PC you can prepare rules.",
