  "Alle Prüfungen bestanden.": "All checks passed.",
  "Alle prüfen": "Check all",
  "Alles, was der PC über seine Geräte selbst auslesen kann – Prozessor, Grafik mit Treiber, Audio, Controller, Tastaturen und Mäuse, Monitore, Laufwerke und Netzwerk. Was nicht lesbar ist, steht mit Grund da.": "Everything the PC can read about its own devices – processor, graphics with driver, audio, controllers, keyboards and mice, monitors, drives and network. Whatever can't be read is listed with the reason.",
