  "Controller testen (Vibration, Sticks)": "Test controllers (vibration, sticks)",
  "Der Fehlerbericht wird vom PC gelöscht. Der Windows-Absturzbericht selbst bleibt.": "The error report is deleted from the PC. The Windows crash report itself stays.",
  "Der PC sammelt zur letzten Sitzung dieses Spiels die Windows-Absturzberichte, Spielversion, Systemdaten und Änderungen davor.": "For this game's last session, the PC collects Windows crash reports, the game version, system data and changes made before it.",
  "Einzelheiten je Plugin unter „Details“ → „Prüfen“. Die Prüfung ändert nichts und führt keinen Plugin-Code aus.": "Per-plugin details under “Details” → “Check”. Checking changes nothing and runs no plugin code.",
  "Ersetzt Benutzername, PC-Name und E-Mail-Adressen. Der Bericht wird nirgends hochgeladen – du entscheidest, wem du die Datei gibst.": "Replaces user name, PC name and email addresses. The report is never uploaded – you decide who gets the file.",
  "Fehler gefunden": "errors found",
  "Fehlerbaustein": "Faulting module",
