  "Fehlerberichte": "Error reports",
  "Fehlerberichte durchsuchen": "Search error reports",
  "Fehlerberichte liegen auf dem PC – sie erscheinen, sobald er verbunden ist.": "Error reports are stored on the PC – they appear as soon as it is connected.",
  "Gelesen {d}": "Read {d}",
  "Gelöscht": "Deleted",
  "Gut so. Stürzt ein Spiel ab, erscheint hier automatisch ein Bericht – du bekommst dazu eine Benachrichtigung.": "Good. If a game crashes, a report appears here automatically – and you get a notification.",
  "Hardware": "Hardware",
  "Hardware-Inventar": "Hardware inventory",
  "Headset (nach Name)": "Headset (by name)",
  "Hervorgehoben: Werte, die sich unterscheiden. Gleicher Fehlerbaustein und Code in mehreren Berichten deuten auf dieselbe Ursache hin.": "Highlighted: values that differ. The same faulting module and code in several reports point to the same cause.",
  "Kein Windows-Absturzbericht für dieses Spiel in diesem Zeitraum gefunden.": "No Windows crash report found for this game in this period.",
  "Keine Fehlerberichte": "No error reports",
  "Keine gefunden.": "None found.",
  "Letzter Start": "Last launch",
  "Mögliche Ursachen (Vermutungen)": "Possible causes (guesses)",
  "Nach einem Absturz oder einem sehr kurzen Spiel legt der PC einen Bericht an: Windows-Absturzbericht, Spielversion, System, Gaming-Profil und Änderungen kurz davor. Mögliche Ursachen sind immer nur Vermutungen – mit Begründung.": "After a crash or a very short game the PC creates a report: Windows crash report, game version, system, gaming profile and changes just before. Possible causes are always only guesses – with a reason.",
  "Nur Anzeige: Von hier wird kein Treiber installiert und keine Einstellung geändert.": "Display only: no driver is installed and no setting is changed from here.",
  "Ohne PC: Stand vom {d}. Neu einlesen geht erst, wenn der PC verbunden ist.": "Without the PC: as of {d}. Re-reading works once the PC is connected.",
