  "Anlass (optional)": "Occasion (optional)",
  "Auf allen verbundenen Geräten: Benachrichtigungen, Dashboard-Widgets, Chats, Dateien und Aufnahmen werden in dieser App verdeckt.": "On all connected devices: notifications, dashboard widgets, chats, files and captures are covered in this app.",
  "Auslösen: Schild oben in der Leiste oder eine Deck-Taste „Datenschutzmodus“. Wird nie für später vorgemerkt.": "Trigger: the shield in the top bar or a Deck key “Privacy mode”. Never queued for later.",
  "Beim Einschalten passiert:": "When switched on:",
  "Benachrichtigungen leise": "Quiet notifications",
  "Datenschutz- und Notfalltaste": "Privacy & emergency button",
  "Datenschutzmodus an/aus": "Privacy mode on/off",
  "Datenschutzmodus an: {n} Schritte wirken": "Privacy mode on: {n} steps in effect",
  "Datenschutzmodus an: {n} Schritte wirken, {b} nicht möglich": "Privacy mode on: {n} steps in effect, {b} not possible",
  "Datenschutzmodus aus": "Privacy mode off",
  "Datenschutzmodus ist an": "Privacy mode is on",
  "Datenschutzmodus ist an – öffnen": "Privacy mode is on – open",
  "Dein Mikrofon geht dann nicht mehr über das virtuelle Kabel (z. B. zu Discord).": "Your microphone then no longer goes through the virtual cable (e.g. to Discord).",
  "Der PC macht automatisch eine vor Mod-Installationen und vor dem Zurückholen von Konfigurationsdateien (höchstens alle 10 Minuten). Konfigurationsdateien kommen nur hinein, wenn sie im Savegame-Tresor eingetragen sind.": "The PC makes one automatically before mod installs and before restoring configuration files (at most every 10 minutes). Configuration files are only included if they are registered in the savegame vault.",
  "Der Zustand davor ist als eigene Momentaufnahme gespeichert.": "The state before was saved as its own snapshot.",
  "Die Schritte festlegen darf nur ein Gerät mit dem Recht „Bearbeiten“.": "Only a device with the “Edit” right may set the steps.",
  "Discord, Spiele und andere Programme werden davon nicht stummgeschaltet oder versteckt.": "Discord, games and other programs are not muted or hidden by this.",
  "Inhalte auf diesem Gerät verdecken": "Cover content on this device",
  "Inhalte auf diesem Gerät verdeckt – die Schritte am PC gehen erst mit Verbindung.": "Content covered on this device – the PC steps need a connection.",
  "Inhalte verdecken": "Cover content",
  "Inhalte wieder sichtbar": "Content visible again",
  "Jetzt einschalten": "Switch on now",
  "Keine Windows-Hinweise und keine Push-Nachrichten; gespeichert werden sie weiter.": "No Windows pop-ups and no push messages; they are still stored.",
  "Konfigurationsdateien kommen nur hinein, wenn sie im Savegame-Tresor für dieses Spiel eingetragen sind.": "Configuration files are only included if they are registered in the savegame vault for this game.",
  "Kopien fehlen: {l} – diese Dateien bleiben unverändert.": "Copies missing: {l} – these files stay unchanged.",
  "Meldet alle anderen Geräte ab, bis der Modus aus ist – der PC und das einschaltende Gerät bleiben. Die Kopplung bleibt bestehen.": "Signs out all other devices until the mode is off – the PC and the device switching it on stay. Pairings are kept.",
  "Mikrofon-Durchleitung aus": "Mic passthrough off",
  "Momentaufnahme": "Snapshot",
  "Momentaufnahme erstellen": "Create snapshot",
  "Momentaufnahme gespeichert": "Snapshot saved",
  "Momentaufnahme löschen?": "Delete snapshot?",
  "Momentaufnahmen liegen auf dem PC – sie erscheinen, sobald er verbunden ist.": "Snapshots are stored on the PC – they appear once it is connected.",
  "Momentaufnahmen vor größeren Änderungen: Spielversion, Startargumente, verknüpftes Gaming-Profil, Konfigurationsdateien aus dem Savegame-Tresor, Mods an/aus, Plugin-Versionen und System. Vergleichen und zurückholen – kein Windows-Abbild.": "Snapshots before bigger changes: game version, launch arguments, linked gaming profile, configuration files from the savegame vault, mods on/off, plugin versions and system. Compare and restore – not a Windows image.",
  "Nicht enthalten:": "Not included:",
  "Noch kein Schritt gewählt – unter „Schritte einstellen“ auswählen.": "No step chosen yet – choose under “Set steps”.",
  "Noch keine Momentaufnahmen": "No snapshots yet",
  "Nur Momentaufnahmen desselben Spiels lassen sich vergleichen.": "Only snapshots of the same game can be compared.",
  "Nur diese (keine Auswahl = alle):": "Only these (none selected = all):",
  "Ohne PC: Liste vom {d}. Erstellen, Vergleichen und Zurückholen gehen nur mit dem PC.": "Without the PC: list from {d}. Creating, comparing and restoring need the PC.",
  "Schaltet das Standard-Mikrofon in Windows stumm und beim Ausschalten wieder ein – nur, wenn die Taste es stummgeschaltet hat.": "Mutes the default microphone in Windows and unmutes it when switched off – only if the button muted it.",
  "Schritte der Datenschutztaste ändern": "Change privacy button steps",
  "Schritte einstellen": "Set steps",
  "Seit {d} · eingeschaltet von {b}": "Since {d} · switched on by {b}",
  "Sobald der Datenschutzmodus am PC aus ist, verbindet sich dieses Gerät von selbst wieder. Angezeigt wird bis dahin der letzte Stand.": "As soon as privacy mode is off on the PC, this device reconnects by itself. Until then the last state is shown.",
  "Soundboard stoppen": "Stop soundboard",
  "Soundboard, Mikrofon, Benachrichtigungen und andere Geräte steuert der PC – das geht erst mit Verbindung und wird nicht für später vorgemerkt. Verdecken kannst du die Inhalte auf diesem Gerät aber sofort.": "Soundboard, microphone, notifications and other devices are controlled by the PC – that needs a connection and is not queued. You can cover the content on this device right away, though.",
  "Spielzustand": "Game state",
  "Teilweise zurückgeholt": "Partly restored",
  "Verdeckt Benachrichtigungen, Dashboard-Widgets, Chats, Dateien und Aufnahmen nur hier – geht auch ohne PC. Antippen zeigt einen verdeckten Bereich kurz.": "Covers notifications, dashboard widgets, chats, files and captures only here – works without the PC too. Tapping shows a covered area briefly.",
  "Vom PC pausiert (Datenschutzmodus)": "Paused by the PC (privacy mode)",
  "Was": "What",
  "Was sich ändert (jetzt → Momentaufnahme):": "What changes (now → snapshot):",
  "Was soll die Taste tun?": "What should the button do?",
  "Windows-Mikrofon stumm": "Windows microphone muted",
  "Windows-Mikrofon stummschalten": "Mute Windows microphone",
  "Zuletzt zurückgeholt {d} von {b}: {e}": "Last restored {d} by {b}: {e}",
  "Zum Savegame-Tresor": "To the savegame vault",
  "Zurückgestellt werden Startargumente, Arbeitsordner, verknüpftes Gaming-Profil, Konfigurationsdateien und Mods an/aus. Vorher speichert der PC den jetzigen Zustand.": "Restored are launch arguments, working folder, linked gaming profile, configuration files and mods on/off. Before that the PC saves the current state.",
  "Zurückholen: {r}": "Restore: {r}",
  "entfernt (war „{v}“)": "removed (was “{v}”)",
