  "Dein Stand (zuletzt erreichtes Kapitel)": "Your progress (last chapter reached)",
  "Dein eigenes Nachschlagewerk: Seiten zu Spielen, Bossen, Rezepten, Strategien – verlinkt mit [[Seitenname]]. Gespeichert auf diesem Gerät, auch ohne PC.": "Your own reference: pages about games, bosses, recipes, strategies – linked with [[page name]]. Stored on this device, also without the PC.",
  "Deine Notiz vom {d}": "Your note from {d}",
  "Deine Sammlungen werden in diesem Browser gespeichert und funktionieren auch, wenn der PC aus ist. Ist der PC verbunden, wird mit seiner Kopie abgeglichen – so sehen deine anderen Geräte dasselbe, und alles ist im PC-Backup.": "Your collections are stored in this browser and also work while the PC is off. When the PC is connected they are compared with its copy – so your other devices see the same, and everything is in the PC backup.",
  "Deine eigene Zusammenfassung: Kapitel, Figuren, offene Fragen und wie weit du bist. Die spoilerfreie Ansicht zeigt nichts, was hinter deinem Stand liegt oder als Spoiler markiert ist.": "Your own summary: chapters, characters, open questions and how far you are. The spoiler-free view shows nothing beyond your progress or marked as a spoiler.",
  "Der Eintrag wird auf allen Geräten gelöscht.": "The entry is deleted on all devices.",
  "Die Spieleliste kommt vom PC – solange sie fehlt, einfach den Namen eintippen.": "The game list comes from the PC – until it is there, just type the name.",
  "Die Story wird auf allen Geräten gelöscht.": "The story is deleted on all devices.",
  "Die jetzige Version von „{n}“ wird ersetzt. Sie bleibt dabei selbst als Konflikt-Kopie auf dem PC.": "The current version of “{n}” is replaced. It stays on the PC as a conflict copy itself.",
  "Diese Seite ist noch leer.": "This page is still empty.",
  "Diese Version wiederherstellen?": "Restore this version?",
  "Dieser Browser erlaubt kein dauerhaftes Speichern (z. B. privates Fenster). Verbinde den PC, damit nichts verloren geht, oder exportiere eine Datei.": "This browser does not allow lasting storage (e.g. private window). Connect the PC so nothing is lost, or export a file.",
  "Dieser Browser speichert nicht (privates Fenster?) – nur bis zum Schließen": "This browser does not store (private window?) – only until closed",
  "Doppelte Seiten": "Duplicate pages",
  "Eigene Etappen mit Belohnungen und Meilensteinen. Kein Druck: keine täglichen Pflichten, keine Fristen, keine Serien, die reißen können.": "Your own stages with rewards and milestones. No pressure: no daily duties, no deadlines, no streaks that can break.",
