  "3×3, 4×4 oder 5×5 – aus Vorlagen, eigenen Aufgaben oder von der KI zum gewählten Spiel. Reihen, Spalten und Diagonalen werden erkannt.": "3×3, 4×4 or 5×5 – from templates, your own tasks or the AI for the chosen game. Rows, columns and diagonals are detected.",
  "Alle Spiele (außer durchgespielt)": "All games (except finished)",
  "Allgemeine Vorschläge passen nicht zu jedem Spiel („falls das Spiel es erlaubt“). Vorschläge „aus deinen Daten“ stammen aus Backlog, Verlauf, Zielpfaden und Funden. Geprüfte spielspezifische Challenges gibt es nur, wenn du sie selbst anlegst – Nexus erfindet keine.": "General ideas don't fit every game (“if the game allows it”). Ideas “from your data” come from backlog, history, goal paths and finds. Verified game-specific challenges only exist if you create them yourself – Nexus does not make any up.",
