  "Für das gewählte Spiel, so viele wie die Größe braucht. Dafür braucht es die Lokale KI (Ollama, 0 €) oder Claude – einrichten unter KI-Assistent.": "For the chosen game, as many as the size needs. This requires the local AI (Ollama, free) or Claude – set up under AI assistant.",
