  "Dateigröße": "File size",
  "Deine Screenshots als Galerie – auf diesem Gerät gespeichert und mit dem PC abgeglichen. Gespeichert wird eine Kopie mit höchstens 1600 px; das Original bleibt, wo es ist. Bilder vom PC holst du unter „Sortieren“ dazu.": "Your screenshots as a gallery – stored on this device and synced with the PC. A copy of at most 1600 px is stored; the original stays where it is. Add pictures from the PC under “Sort”.",
  "Die Datei ist in der Aufnahme-Liste des PCs gerade nicht zu sehen (verschoben, gelöscht oder PC noch nicht verbunden).": "The file is not in the PC's capture list right now (moved, deleted or the PC is not connected yet).",
