  "Momente": "Moments",
  "Nur offizielle Seiten (Spotify, Apple Music, YouTube, Bandcamp, Steam …). Nexus spielt nichts selbst ab und lädt nichts herunter.": "Official sites only (Spotify, Apple Music, YouTube, Bandcamp, Steam …). Nexus plays nothing itself and downloads nothing.",
