  "Was passiert": "What happens",
  "YouTube, Twitch-Video oder direkte Videodatei: dann springen Momente an die Stelle. Andere Seiten öffnen am Anfang.": "YouTube, Twitch video or a direct video file: moments then jump to the spot. Other sites open at the start.",
