  "Gerade verbunden: {n}": "Connected right now: {n}",
  "Handy koppeln (Geräte → Gerät koppeln, QR-Code scannen)": "Pair a phone (Devices → Pair device, scan the QR code)",
  "Kein gekoppeltes Gerät ist gerade verbunden.": "No paired device is connected right now.",
  "Noch kein Handy oder Tablet gekoppelt.": "No phone or tablet paired yet.",
  "{n} gekoppelt": "{n} paired",
  "Beim PC öffnen und koppeln": "Open on the PC and pair",
  "Die Adresse beginnt mit http:// – mit ihr verbindet sich nur die Seite, die der PC selbst anbietet. Der Knopf öffnet sie mit dem Code; Handy und PC müssen im selben WLAN sein. Tipp: Diese Seite danach zum Startbildschirm hinzufügen. Von unterwegs geht es nur mit einer https-Adresse des PCs (z. B. Tailscale Funnel).": "The address starts with http:// – only the page the PC offers itself can connect with it. The button opens it with the code; phone and PC must be on the same Wi-Fi. Tip: add that page to your home screen afterwards. From outside your home it only works with an https address of the PC (e.g. Tailscale Funnel).",
  "Diese Website (https) darf eine http-Adresse im Heimnetz nicht öffnen – das blockiert der Browser. Nimm „Beim PC öffnen und koppeln“ unten (oder scanne den QR-Code am PC mit der Kamera).": "This website (https) may not open an http address in the home network – the browser blocks it. Use “Open on the PC and pair” below (or scan the QR code on the PC with the camera).",
  "Im Heimnetz direkt beim PC koppeln": "Pair directly with the PC in the home network",
  "Die Bibliothek am PC ist noch leer.": "The library on the PC is still empty.",
  "Noch keine Spiele in der Bibliothek": "No games in the library yet",
  "Unter „Spiele“ → „Hinzufügen“": "Under “Games” → “Add”",
  "findest du Steam- und Epic-Spiele; andere Spiele und Programme gibst du dort als Datei frei.": "you find Steam and Epic games; other games and programs you share there as a file.",
  "Abgleich fertig": "Sync done",
  "Abgleich fertig – Fehler bei: {l}": "Sync done – failed for: {l}",
  "Deine installierten Spiele aus der Xbox-App (Ordner „XboxGames“, auf allen Laufwerken) erscheinen dann automatisch in der Bibliothek und starten über Windows. Kein Login nötig.": "Your installed games from the Xbox app (“XboxGames” folders on all drives) then appear in the library automatically and start through Windows. No login needed.",
  "Installierte Spiele von Steam, Epic, EA und der Xbox-App kommen automatisch hierher – kurz nach dem Start des Begleiters und danach alle 10 Minuten. Fehlt ein Spiel, lass den PC suchen oder gib eine EXE-Datei frei.": "Installed games from Steam, Epic, EA and the Xbox app come here automatically – shortly after the companion starts and every 10 minutes after that. If a game is missing, let the PC search or share an EXE file.",
  "Bei {s} ansehen": "View on {s}",
  "Key-Shops (Deutschland)": "Key shops (Germany)",
  "Kein Preis hier: Instant Gaming und Eneba bieten keine öffentliche Preisabfrage und sperren automatische Abfragen. Die Links öffnen die Suche mit Euro-Preisen. Achte auf die Region des Keys (Europa oder Global) und die Plattform (Steam, Xbox …).": "No price here: Instant Gaming and Eneba offer no public price lookup and block automated queries. The links open the search with euro prices. Check the key's region (Europe or Global) and the platform (Steam, Xbox …).",
  "Alle Angebote bei GG.deals": "All offers on GG.deals",
  "Braucht die Steam-App-ID des Spiels.": "Needs the game's Steam app ID.",
  "Eintragen geht am PC (dort hat die App Admin-Rechte).": "Enter it at the PC (the app has admin rights there).",
  "GG.deals-API-Schlüssel": "GG.deals API key",
  "GG.deals-Schlüssel entfernt": "GG.deals key removed",
  "GG.deals-Schlüssel gespeichert – Preise kommen mit der nächsten Prüfung": "GG.deals key saved – prices come with the next check",
  "Key-Shop-Preise (GG.deals)": "Key shop prices (GG.deals)",
  "Key-Shops ({c})": "Key shops ({c})",
  "Mit einem kostenlosen API-Schlüssel von GG.deals zeigt der Deal Radar den günstigsten Key-Shop-Preis (Instant Gaming, Eneba und viele mehr) und den Tiefstpreis. Schlüssel: bei gg.deals anmelden und in deinem Konto einen API-Schlüssel erstellen (gg.deals/api). Er bleibt verschlüsselt auf dem PC; der PC fragt bei jeder Prüfung api.gg.deals mit den Steam-App-IDs deiner Wunschliste.": "With a free GG.deals API key the Deal Radar shows the cheapest key shop price (Instant Gaming, Eneba and many more) and the historical low. Key: sign in at gg.deals and create an API key in your account (gg.deals/api). It stays encrypted on the PC; at every check the PC asks api.gg.deals with the Steam app IDs of your wish list.",
  "Preise mit kostenlosem GG.deals-Schlüssel (Einstellungen unten). Ohne Schlüssel: Links zum Nachschauen.": "Prices with a free GG.deals key (settings below). Without a key: links to look it up.",
  "Prüfen & speichern": "Check & save",
  "Tiefstpreis {p}": "Lowest {p}",
  "ab {p}": "from {p}",
  "günstigster Key-Shop laut GG.deals (Instant Gaming, Eneba und viele mehr), geprüft {d} – nicht jeder Key ist ein Steam-Key, Region und Plattform im Shop prüfen": "cheapest key shop according to GG.deals (Instant Gaming, Eneba and many more), checked {d} – not every key is a Steam key, check region and platform in the shop",
  "offizielle Shops ab {p}": "official stores from {p}",
  "In einem Key-Shop gerade am günstigsten (laut GG.deals).": "Cheapest in a key shop right now (according to GG.deals).",
