  "Adresse dieser Seite": "Address of this page",
  "Als App auf den Home-Bildschirm": "Add as app to the home screen",
  "Als App zum Home-Bildschirm hinzufügen; in Chrome/Edge die Seite installieren.": "Add it as an app to the home screen; in Chrome/Edge install the page.",
  "Andere Adresse nutzen": "Use another address",
  "App": "App",
  "Dauerhaft auf diesem Gerät": "Permanently on this device",
  "Dauerhafter Speicher": "Persistent storage",
  "Der Browser löscht die Kopplung nicht von selbst.": "The browser does not delete the pairing on its own.",
  "Der Link in der Adresszeile gilt 10 Minuten und nur einmal. Die Home-Bildschirm-App hat auf iPhone und iPad einen eigenen Speicher – deshalb braucht sie diesen eigenen Zugang. Android/Chrome: Menü → „App installieren“.": "The link in the address bar is valid for 10 minutes and only once. On iPhone and iPad the home-screen app has its own storage – that is why it needs its own access. Android/Chrome: menu → “Install app”.",
  "Der PC hat nicht rechtzeitig geantwortet. Ob der Befehl ausgeführt wurde, ist unklar – er wird nicht automatisch wiederholt.": "The PC did not answer in time. Whether the command ran is unknown – it is not repeated automatically.",
  "Der PC kennt keine weitere Adresse. Eine feste Adresse gibt es mit einem Router-Namen (z. B. FRITZ!Box) oder mit Tailscale – siehe Diagnose → „Feste Adresse“.": "The PC knows no other address. A fixed address comes with a router name (e.g. FRITZ!Box) or with Tailscale – see Diagnostics → “Fixed address”.",
  "Die App vom Home-Bildschirm öffnen – sie meldet sich selbst an und erscheint als eigenes Gerät in der Liste.": "Open the app from the home screen – it signs in by itself and appears as its own device in the list.",
  "Diese Website (https) darf den PC im WLAN nicht direkt erreichen. Im WLAN läuft die App direkt vom PC unter {u} – dort ist dieses Gerät gekoppelt. Tipp: Diese PC-Seite zum Home-Bildschirm hinzufügen (Geräte & Verbindungen → „Als App auf den Home-Bildschirm“).": "This website (https) may not reach the PC in the Wi-Fi directly. In the Wi-Fi the app runs straight from the PC at {u} – this device is paired there. Tip: add that PC page to the home screen (Devices & connections → “Add as app to the home screen”).",
  "Eigene https-Adresse": "Own https address",
  "Gekoppelt unter {h}": "Paired at {h}",
  "Geräte & Verbindungen → „Als App auf den Home-Bildschirm“ – damit ist die App sofort gekoppelt.": "Devices & connections → “Add as app to the home screen” – the app is paired right away.",
  "Geräte & Verbindungen → „Andere Adresse nutzen“ (Router-Name oder Tailscale), oder im Router dem PC immer dieselbe IP geben.": "Devices & connections → “Use another address” (router name or Tailscale), or give the PC a fixed IP in the router.",
  "Home-Bildschirm-App": "Home-screen app",
  "IP-Adresse – ändert der Router sie, ist die Kopplung hier weg.": "IP address – if the router changes it, the pairing here is gone.",
  "Im WLAN: „Zur PC-App (WLAN)“ oben benutzen ({u}).": "In the Wi-Fi: use “To the PC app (Wi-Fi)” at the top ({u}).",
  "Jetzt in Safari unten (iPhone) bzw. oben (iPad) auf das Teilen-Symbol tippen.": "Now tap the share icon in Safari at the bottom (iPhone) or top (iPad).",
  "Läuft als App vom Home-Bildschirm – sie hat einen eigenen Speicher und eine eigene Kopplung.": "Runs as an app from the home screen – it has its own storage and its own pairing.",
  "Läuft im Browser. Eine App vom Home-Bildschirm hat auf iPhone/iPad einen eigenen Speicher.": "Runs in the browser. An app from the home screen has its own storage on iPhone/iPad.",
  "Nicht zugesichert – der Browser darf Daten bei Platzmangel oder langer Nichtnutzung löschen (Safari: nach 7 Tagen ohne Besuch, nicht für Home-Bildschirm-Apps).": "Not guaranteed – the browser may delete data when space is low or after long non-use (Safari: after 7 days without a visit, not for home-screen apps).",
  "Router-Name (fest im WLAN)": "Router name (fixed in the Wi-Fi)",
  "Tailscale (auch unterwegs)": "Tailscale (also on the go)",
  "Tailscale (https, auch unterwegs)": "Tailscale (https, also on the go)",
  "Unter jeder Adresse merkt sich der Browser die Kopplung getrennt. Mit diesem Link bekommt die gewählte Adresse einen eigenen Zugang (10 Minuten gültig, einmal).": "The browser keeps the pairing separately for every address. With this link the chosen address gets its own access (valid 10 minutes, once).",
  "WLAN-IP (kann sich ändern)": "Wi-Fi IP (can change)",
  "Zur PC-App (WLAN)": "To the PC app (Wi-Fi)",
  "{h} (Website) – erreicht den PC nur über eine https-Adresse (Tailscale/Relay), nicht über die WLAN-Adresse.": "{h} (website) – reaches the PC only through an https address (Tailscale/relay), not through the Wi-Fi address.",
  "{h} ist eine IP-Adresse. Gibt der Router dem PC eine andere, ist die Kopplung unter dieser Adresse weg.": "{h} is an IP address. If the router gives the PC another one, the pairing under this address is gone.",
  "{h} – direkt am PC": "{h} – directly on the PC",
  "{h} – fester Name, bleibt auch bei neuer IP gleich": "{h} – fixed name, stays the same with a new IP",
  "„Zum Home-Bildschirm“ wählen und „Hinzufügen“.": "Choose “Add to Home Screen” and “Add”.",
  "Im WLAN läuft die App direkt vom PC unter {u} – diese Website (https) darf den PC dort nicht erreichen.": "In the Wi-Fi the app runs straight from the PC at {u} – this website (https) may not reach the PC there.",
  "Abhängen": "Take down",
  "Abzeichen für das, was du hier wirklich angelegt hast – gezählt aus deinen gespeicherten Einträgen. Löschst du die Einträge, ist auch das Abzeichen wieder offen. Die Stufen sind nur Optik.": "Badges for what you really created here – counted from your saved entries. If you delete the entries, the badge is open again. The tiers are only a look.",
