  "Am PC den Nexus Gaming Hub starten (Symbol im Infobereich) – mit „Mit Windows starten“ ist er nach jedem Neustart da.": "Start Nexus Gaming Hub on the PC (icon in the notification area) – with “Start with Windows” it is there after every restart.",
  "Am PC entfernt – dieses Gerät hat keinen Zugriff mehr.": "Removed on the PC – this device has no access any more.",
  "Am PC unter Geräte → dieses Gerät → Berechtigungen „Starten“ erlauben.": "On the PC under Devices → this device → permissions, allow “Start”.",
  "Am PC unter Spiele oder Programme etwas freigeben (installierte Steam-, Epic-, EA- und Xbox-Spiele kommen von selbst).": "Share something on the PC under Games or Programs (installed Steam, Epic, EA and Xbox games come by themselves).",
  "Am PC „Gerät koppeln“ öffnen und den Code hier eingeben oder den QR-Code scannen.": "Open “Pair device” on the PC and enter the code here or scan the QR code.",
