  "Erst nach der Anmeldung prüfbar.": "Can be checked after signing in.",
  "Erst nach der Anmeldung prüfbar. Deck-Tasten lassen sich schon vorbereiten, gestartet wird erst mit Verbindung.": "Can be checked after signing in. Deck keys can already be prepared; starting needs the connection.",
  "Geprüft {t}": "Checked {t}",
  "Gerät autorisiert": "Device authorised",
  "Gerät nicht autorisiert – bitte neu koppeln.": "Device not authorised – please pair again.",
  "Geräteverbindung aktiv": "Device connection active",
  "Hinweis: Eine https-Website erreicht den PC nur über eine https-Adresse – Details in den Prüfungen 2 und 4.": "Note: an https website reaches the PC only through an https address – details in checks 2 and 4.",
  "Im VPN „Zugriff auf lokales Netzwerk“ bzw. Split-Tunneling erlauben oder das VPN kurz ausschalten. Unterwegs: Tailscale (am PC und Handy) oder das Relay nutzen.": "Allow “local network access” or split tunnelling in the VPN, or switch the VPN off briefly. On the go: use Tailscale (on PC and phone) or the relay.",
  "Im WLAN die App direkt vom PC öffnen, oder für die Website eine https-Adresse (Tailscale/Relay) einrichten.": "In the Wi-Fi open the app straight from the PC, or set up an https address (Tailscale/relay) for the website.",
  "Ist am Handy ein VPN aktiv? Viele VPNs leiten auch Verbindungen ins Heimnetz um – dann im VPN „Zugriff auf lokales Netzwerk“ erlauben oder es kurz ausschalten. Diagnose zeigt Details.": "Is a VPN active on the phone? Many VPNs also redirect connections to the home network – then allow “local network access” in the VPN or switch it off briefly. Diagnostics shows details.",
  "Ist am Handy ein VPN aktiv? Viele VPNs leiten auch Verbindungen ins Heimnetz um – dann ist der PC nicht erreichbar.": "Is a VPN active on the phone? Many VPNs also redirect connections to the home network – then the PC cannot be reached.",
  "Keine Antwort vom Begleiter.": "No answer from the companion.",
  "Keine PC-Adresse gespeichert.": "No PC address saved.",
  "Letzter Herzschlag vor {s} s (alle 15 s, im Hintergrund alle 60 s)": "Last heartbeat {s} s ago (every 15 s, in the background every 60 s)",
  "Läuft der Relay-Server? Die App versucht es automatisch weiter (alle paar Sekunden).": "Is the relay server running? The app keeps trying by itself (every few seconds).",
  "Mit dem Geräteschlüssel angemeldet (Sitzung wird bei Bedarf selbst erneuert)": "Signed in with the device key (the session renews itself when needed)",
