  "Braucht den PC: Steam erlaubt die Abfrage nicht direkt aus dem Browser. Ohne PC kannst du Patchnotes einfügen (Neu).": "Needs the PC: Steam does not allow this request directly from the browser. Without the PC you can paste patch notes (New).",
  "Budget (nur Wunschliste mit gemessenem Preis)": "Budget (only wish list entries with a measured price)",
  "DLC": "DLC",
  "DLC / Erweiterung": "DLC / expansion",
  "DLCs": "DLCs",
