  "Doppelt in deinem Besitz: {l}": "Owned twice: {l}",
  "Editionen & DLCs": "Editions & DLCs",
  "Editionen, DLCs und Pässe eines Spiels nebeneinander: was steckt wo drin, was hast du schon (selbst markiert) – und wo würdest du doppelt kaufen.": "Editions, DLCs and passes of a game side by side: what is in which, what you already have (marked by you) – and where you would buy something twice.",
  "Eigene Liste kommender Spiele, DLCs und Updates. „Bestätigt“ nur mit offizieller Quelle; alles andere bleibt sichtbar als unbestätigt markiert. Nichts wird automatisch eingetragen.": "Your own list of upcoming games, DLCs and updates. “Confirmed” only with an official source; everything else stays visibly marked as unconfirmed. Nothing is added automatically.",
