  "Patchnotes mit Version, Datum und Quelle. Die Sortierung hilft beim Überblick – der Originaltext bleibt unverändert gespeichert. Filter „Gelesen“ und Spiel oben.": "Patch notes with version, date and source. The sorting helps to get an overview – the original text is kept unchanged. Filter “Read” and game above.",
