  "Priorität: {p}": "Priority: {p}",
  "Regelbasiert aus deinen eigenen Angaben: gleiche Stichwörter bei „Genre & Spielgefühl“ (3 Punkte), gleiche Bibliotheks-Kategorie (2), gleiche Spielweise laut Faktencheck (1). Jeder Grund wird angezeigt – keine KI, keine fremde Datenbank.": "Rule-based from your own entries: same keywords in “Genre & feel” (3 points), same library category (2), same way of playing according to the fact check (1). Every reason is shown – no AI, no outside database.",
  "Release": "Release",
  "Releases": "Releases",
  "Releases, Events, Patchnotes, Fakten, Barrierefreiheit, Editionen und Empfehlungen – nur mit deinen Angaben oder offiziellen Quellen, Unbekanntes bleibt als unbekannt markiert.": "Releases, events, patch notes, facts, accessibility, editions and recommendations – only from your entries or official sources, anything unknown stays marked as unknown.",
  "Saisons & Events": "Seasons & events",
  "Saisons, Events und Battle Passes, die du selbst einträgst – mit der Zeitzone aus der Ankündigung. Gezeigt wird immer auch deine Ortszeit. Ohne Ende wird nicht behauptet, dass etwas noch läuft.": "Seasons, events and battle passes you enter yourself – with the time zone from the announcement. Your local time is always shown too. Without an end it is never claimed that something is still running.",
