  "Hier ist dein {s}×{s}-Bingo für {g} ({d}{m}) mit {n} Aufgaben. Tippe ein Feld an, wenn du die Aufgabe geschafft hast.": "Here is your {s}×{s} bingo for {g} ({d}{m}) with {n} tasks. Tap a field when you have done the task.",
  "Hinweis: Freebuff ist ein Programmier-Werkzeug – sein kostenloses DeepSeek-Kontingent kann diese Website nicht nutzen. Dafür braucht es einen eigenen DeepSeek-API-Schlüssel. Mit DeepSeek gehen Spielname, Einstellungen und ausgeschlossene Aufgaben an DeepSeek, sonst nichts.": "Note: Freebuff is a coding tool – this website cannot use its free DeepSeek quota. That needs your own DeepSeek API key. With DeepSeek the game name, settings and excluded tasks go to DeepSeek, nothing else.",
