  "Für dieses Spiel gibt es keine eigenen Katalog-Aufgaben – die Aufgaben sind allgemein. Mit einer KI am PC werden sie spielspezifisch.": "There are no catalog tasks of its own for this game – the tasks are general. With an AI on the PC they become specific to the game.",
  "Battle Royale – Karte und Gegenstände wechseln mit jeder Saison, die Aufgaben bleiben deshalb allgemein": "Battle royale – map and items change every season, so the tasks stay general",
