  "Deine Sammlungen und dein Design auf diesem Gerät – ohne PC nutzbar. Bereiche wählen, dann als Datei, Tabelle oder PDF sichern.": "Your collections and design on this device – usable without the PC. Choose areas, then save them as a file, table or PDF.",
  "Der PC behält die letzten 1000 Sitzungen – ältere sind nicht mehr enthalten.": "The PC keeps the last 1000 sessions – older ones are no longer included.",
  "Der Spielverlauf ist am PC ausgeschaltet – ohne Aufzeichnung gibt es keine Auswertung. (Einstellungen → Datenschutz)": "Play history is turned off on the PC – without recording there are no insights. (Settings → Privacy)",
