  "Die Auswertungen brauchen den PC – dort wird aufgezeichnet, was du wann gespielt hast. Ohne Verbindung wird nichts geschätzt.": "Insights need the PC – it records what you played and when. Without a connection nothing is estimated.",
  "Die Datei ist kein gültiges JSON.": "The file is not valid JSON.",
