  "Diese Links zeigen auf Seiten, die es noch nicht gibt – anlegen oder den Link ändern:": "These links point to pages that do not exist yet – create them or change the link:",
  "Drucken / als PDF speichern": "Print / save as PDF",
  "Du entscheidest, was auf der Karte steht. Geteilt wird nur, was du selbst verschickst – nichts wird hochgeladen.": "You decide what is on the card. Only what you send yourself is shared – nothing is uploaded.",
  "Enthält nur die Anordnung der Widgets – keine Einstellungen, Rechte, Schlüssel oder Programmcode. Deine bisherigen Seiten bleiben unverändert.": "Contains only the widget arrangement – no settings, permissions, keys or program code. Your existing pages stay unchanged.",
