  "Dein PC ruft dafür einmal die Seite dieses Spiels auf keyforsteam.de ab – nur auf Knopfdruck, höchstens alle 5 Sekunden, 6 Stunden gespeichert.": "Your PC fetches this game's page on keyforsteam.de once – only when you tap, at most every 5 seconds, kept for 6 hours.",
