  "Key-Shops sind Marktplätze: Keys stammen nicht immer aus offiziellen Quellen und können vom Anbieter gesperrt werden. Region und Plattform vor dem Kauf prüfen.": "Key shops are marketplaces: keys do not always come from official sources and can be revoked by the publisher. Check region and platform before buying.",
