  "bis": "to",
  "Bedingungen & Ablauf": "Conditions & flow",
  "Profile & Hinweise": "Profiles & notices",
  "Aufnahme & Licht": "Recording & lighting",
  "Dann steht unter „Wo war ich?“ des Spiels: „Challenge geschafft: …“.": "Then the game's “Where was I?” says: “Challenge done: …”.",
  "Geschaffte Challenges im Gaming-Gedächtnis notieren": "Note finished challenges in the gaming memory",
  "Tipp: Frag JARVIS – z. B. „Erstelle fünf mittelschwere Minecraft-Challenges“ oder „sehr schwere Elden-Ring-Challenge ohne Spoiler“. Die Aufgaben kommen aus demselben geprüften Katalog wie das Gaming-Bingo und landen hier.": "Tip: ask JARVIS – e.g. “Create five medium Minecraft challenges” or “very hard Elden Ring challenge without spoilers”. The tasks come from the same checked catalog as the gaming bingo and land here.",
  "JARVIS · geprüfter Katalog": "JARVIS · checked catalog",
  "JARVIS · allgemein fürs Genre": "JARVIS · general for the genre",
  "Abstände": "Spacing",
  "Das Design von vor der ersten Änderung durch den Design-Editor kommt zurück. „Rückgängig“ holt das jetzige wieder.": "The design from before the first change by the design editor comes back. “Undo” brings back the current one.",
  "Design übernommen – „Letzte Designänderung rückgängig“ holt das vorherige zurück": "Design applied – “Undo last design change” brings back the previous one",
  "Design-Vorschau": "Design preview",
  "Deutlich": "Strong",
  "Dezent": "Subtle",
  "Große Schaltflächen (iPad, Touch)": "Large buttons (iPad, touch)",
  "KI-Design-Editor": "AI design editor",
  "Kompakt": "Compact",
  "Luftig": "Roomy",
  "Weich": "Soft",
  "Letzte Designänderung rückgängig": "Undo last design change",
  "Letzte Designänderung rückgängig gemacht": "Last design change undone",
  "Sag JARVIS, wie es aussehen soll – z. B. „Mach mein Dashboard etwas heller“, „Cyberpunk-Stil“, „dunkles Design mit lila Neon-Akzenten“ oder „Schaltflächen größer für mein iPad“. Du siehst erst eine Vorschau und entscheidest dann: Übernehmen oder Verwerfen.": "Tell JARVIS how it should look – e.g. “Make my dashboard a bit brighter”, “cyberpunk style”, “dark design with purple neon accents” or “bigger buttons for my iPad”. You see a preview first and then decide: apply or discard.",
  "Ursprüngliches Design wiederhergestellt": "Original design restored",
  "Ursprüngliches Design wiederherstellen": "Restore original design",
  "Ursprüngliches Design wiederherstellen?": "Restore original design?",
  "Vorschau verworfen": "Preview discarded",
  "noch nicht gespeichert": "not saved yet",
  "Auslastung nicht verfügbar": "Load not available",
  "Beenden": "Close",
  "Beenden bittet das Programm höflich, sich zu schließen – nie erzwungen. Windows-Prozesse, Launcher, Anti-Cheat und Sicherheitssoftware werden nie geschlossen.": "Close politely asks the program to quit – never forced. Windows processes, launchers, anti-cheat and security software are never closed.",
  "CPU max.": "CPU max.",
  "CPU Ø": "CPU avg.",
  "Dafür braucht es zwei Sitzungen mit Leistungsdaten. Die zeichnet der PC beim Spielen auf, wenn „Leistung pro Sitzung aufzeichnen“ an ist.": "This needs two sessions with performance data. The PC records them while you play when “Record performance per session” is on.",
  "Den PC-Bildschirm live sehen und mit Touch-Maus, Tastatur und Scrollen steuern – über die eigene, verschlüsselte Verbindung (WLAN oder Tailscale). Muss am PC einmal erlaubt werden.": "See the PC screen live and control it with touch mouse, keyboard and scrolling – over your own encrypted connection (Wi-Fi or Tailscale). Must be allowed once at the PC.",
  "Der Begleiter am PC ist nicht erreichbar. Ist der PC an und läuft der Begleiter? Ein ausgeschalteter PC lässt sich über die Website nicht steuern.": "The companion on the PC cannot be reached. Is the PC on and the companion running? A switched-off PC cannot be controlled from the website.",
  "Der PC bittet das Programm, sich zu beenden – wie ein Klick auf das X. Nicht gespeicherter Fortschritt kann verloren gehen; manche Spiele fragen vorher nach. Nichts wird erzwungen.": "The PC asks the program to quit – like clicking the X. Unsaved progress can be lost; some games ask first. Nothing is forced.",
