  "Modelle laden": "Load models",
  "Modelle übernehmen": "Apply models",
  "Noch kein Modell gewählt.": "No model chosen yet.",
  "Nur https – oder http für einen Router in deinem Heimnetz. Wechselst du die Adresse, wird der alte Schlüssel gelöscht.": "https only – or http for a router in your home network. Changing the address deletes the old key.",
  "Nur kostenlose Modelle": "Free models only",
