  "Router: {u}{k}": "Router: {u}{k}",
  "Schlüssel (gespeichert – neu eintragen zum Ersetzen)": "Key (saved – enter a new one to replace it)",
  "Trag unten Router-Adresse, Schlüssel und mindestens ein Modell ein – dann wähle „KI-Router“ noch einmal.": "Enter the router address, key and at least one model below – then choose \"AI router\" again.",
  "Trag unten zuerst den Gemini-Schlüssel ein – dann wähle „Gemini“ noch einmal.": "First enter the Gemini key below – then choose \"Gemini\" again.",
  "Trag zuerst den API-Schlüssel ein.": "Enter the API key first.",
  "Wird nur auf diesem PC verschlüsselt gespeichert, nie angezeigt und nie ins Backup geschrieben.": "Stored encrypted only on this PC, never shown and never written to backups.",
  "Kostenlose Modelle enden auf „:free“ (laut OpenRouter 20 Anfragen pro Minute, 50 pro Tag). Schlüssel kostenlos auf openrouter.ai → Keys.": "Free models end in \":free\" (according to OpenRouter 20 requests per minute, 50 per day). Free key at openrouter.ai → Keys.",
  "Kostenloser Tarif mit Tageslimits. Schlüssel kostenlos auf console.groq.com → API Keys.": "Free tier with daily limits. Free key at console.groq.com → API Keys.",
  "Kostenpflichtig (Abrechnung bei MixRoute) – nur nutzen, wenn du dort Guthaben hast.": "Paid (billed by MixRoute) – only use it if you have credit there.",
  "OmniRoute oder LiteLLM auf einem Rechner in deinem Heimnetz – 0 €, Schlüssel nur falls dein Router einen verlangt. Adresse anpassen.": "OmniRoute or LiteLLM on a computer in your home network – €0, key only if your router asks for one. Adjust the address.",
  "als {r}": "as {r}",
  "Eine kleine Leiste oben in der Mitte: JARVIS zeigt, was er gerade tut, fragt bei wichtigen Aktionen (z. B. Herunterfahren) dort nach und öffnet beim Antippen Widgets – laufendes Spiel, Musiktasten, Uhr, Fokus-Timer. Nur auf diesem Gerät.": "A small bar at the top centre: JARVIS shows what he is doing, asks there before important actions (e.g. shutting down) and opens widgets on tap – running game, music keys, clock, focus timer. This device only.",
  "Fokus": "Focus",
  "Fokuszeit vorbei – kurze Pause?": "Focus time is over – short break?",
