  "Schwindelig": "Dizzy",
  "Abgelehnt – nichts ausgeführt.": "Declined – nothing was run.",
  "Auch in Spielen anzeigen": "Also show in games",
  "Auf dem Desktop und in Programmen anzeigen": "Show on the desktop and over programs",
  "Aus: Sobald ein Spiel aus deiner Bibliothek läuft, verschwindet die Insel ganz und kommt danach wieder. Spiele im exklusiven Vollbild verdecken sie ohnehin – das entscheidet Windows.": "Off: as soon as a game from your library runs, the island disappears completely and comes back afterwards. Games in exclusive fullscreen cover it anyway – Windows decides that.",
  "Die Insel gibt es nur im Windows-Begleiter.": "The island is only available in the Windows companion.",
  "Gerade ausgeblendet, weil ein Spiel läuft.": "Hidden right now because a game is running.",
  "Gerade nicht sichtbar.": "Not visible right now.",
  "Gerade sichtbar.": "Visible right now.",
  "JARVIS – antippen für Widgets": "JARVIS – tap for widgets",
  "JARVIS-Insel auf dem PC-Bildschirm": "JARVIS island on the PC screen",
  "Noch nichts gefragt.": "Nothing asked yet.",
  "Oben in der Mitte des Bildschirms sind nur JARVIS' Augen zu sehen. Fährst du mit der Maus darüber, zeigt er, was er tut; antippen öffnet Widgets (laufendes Spiel, Musiktasten, Uhr, Fokus-Timer, Frage an JARVIS). Fragt er nach (z. B. Spiel starten), bestätigst du direkt dort. Auf dem Windows-Sperrbildschirm darf kein Programm etwas anzeigen.": "At the top centre of the screen only JARVIS' eyes are visible. Hover over them and he shows what he is doing; a tap opens widgets (running game, music keys, clock, focus timer, ask JARVIS). When he asks (e.g. start a game), you confirm right there. Windows does not allow any program to show anything on the lock screen.",
  "Zum Einstellen muss der PC verbunden sein.": "The PC must be connected to change this.",
  "Insel oben auf dem PC-Bildschirm": "Island at the top of the PC screen",
  "Zockt mit": "Gaming along",
  "Schläft": "Sleeping",
  "Überrascht": "Surprised",
  "Flach: wie bisher. Glas: durchsichtig mit Unschärfe. Weich 3D: Karten und Knöpfe wie aus Ton – erhaben, Felder eingedrückt. Erhaben 3D: Karten mit Tiefe, Kanten und Licht von oben.": "Flat: as before. Glass: see-through with blur. Soft 3D: cards and buttons like clay – raised, fields pressed in. Raised 3D: cards with depth, edges and light from above.",
  "Karten neigen sich zur Maus (3D)": "Cards lean towards the mouse (3D)",
  "Nur mit Maus und nur ohne „Animationen reduzieren“ – auf Handy und iPad bleibt alles ruhig.": "Mouse only and only without \"Reduce animations\" – on phone and iPad everything stays calm.",
  "Oberfläche": "Surface",
  "Flach": "Flat",
  "Glas": "Glass",
  "Weich 3D": "Soft 3D",
  "Erhaben 3D": "Raised 3D",
  "Glas-Unschärfe: {v} px": "Glass blur: {v} px",
  "Chrom-Streifen": "Chrome stripes",
  "Petrol-Welle": "Teal wave",
  "Sonnenuntergang am Meer": "Sunset at the sea",
  "Milchglas hell": "Frosted light",
  "Sanftes Grau": "Soft grey",
  "Mitternacht": "Midnight",
  "Klar-Glas": "Clear glass",
  "Flach: wie bisher. Glas: durchsichtig mit Unschärfe. Klar-Glas: fast ganz durchsichtig wie bei Apple oder Nothing OS (Deckkraft der Karten regelt, wie klar). Weich 3D: Karten und Knöpfe wie aus Ton – erhaben, Felder eingedrückt. Erhaben 3D: Karten mit Tiefe, Kanten und Licht von oben.": "Flat: as before. Glass: see-through with blur. Clear glass: almost completely see-through like Apple or Nothing OS (the card opacity sets how clear). Soft 3D: cards and buttons like clay – raised, fields pressed in. Raised 3D: cards with depth, edges and light from above.",
  "Stand {d} – der PC ist gerade nicht verbunden": "As of {d} – the PC is not connected right now",
  "Der Speicher dieses Geräts ist voll – der letzte Stand kann nicht ganz gespeichert werden. Browser-Daten der Seite aufräumen schafft Platz.": "This device's storage is full – the last state cannot be saved completely. Clearing this site's browser data frees up space.",
  "Ich tanze!": "I'm dancing!",
