  "Läuft gerade: {g}": "Running now: {g}",
  "Status-Pille unter der oberen Leiste (Handy und iPad)": "Status pill under the top bar (phone and tablet)",
  "Zeigt Verbindung, laufendes Spiel und wartende Änderungen; antippen für Details. Eine eigene Anzeige in der Seite – keine echte Dynamic Island des iPhones. Gilt nur für dieses Gerät.": "Shows connection, running game and waiting changes; tap for details. Its own display inside the page – not a real iPhone Dynamic Island. Applies to this device only.",
  "Aussehen der Insel": "Look of the island",
  "Das Aussehen der Insel stellst du am PC selbst ein (in diesem Fenster am PC).": "You set the look of the island on the PC itself (in this window on the PC).",
  "Wähle eine Vorlage und sieh sie dir an. Erst „Übernehmen“ ändert die echte Insel; „Standard“ ist das bisherige Aussehen.": "Pick a template and look at it. Only “Apply” changes the real island; “Standard” is the previous look.",
