  "Die Farbe für „bereit“. Rückfrage, Fehler, Tanzen und die anderen Stimmungen behalten ihre Farben, damit man den Zustand erkennt.": "The colour for “ready”. Questions, errors, dancing and the other moods keep their colours so the state stays recognisable.",
