  "Hohe Last": "High load",
  "Jedes Design bringt Hintergrund, Glas-Oberfläche und Aufbau der Startseite mit – alles bleibt unten änderbar. Je Spiel: Theme im Gaming-Profil des Spiels.": "Each design brings its own background, glass surface and home screen layout – everything stays changeable below. Per game: theme in the game's gaming profile.",
