  "Dein Schlüssel auf diesem Gerät ist gesperrt – in der KI-Verwaltung entsperren.": "Your key on this device is locked – unlock it in the AI manager.",
  "Dein Schlüssel auf diesem Gerät ist gesperrt – unten in der KI-Verwaltung entsperren, dann antwortet OpenRouter bzw. Groq.": "Your key on this device is locked – unlock it in the AI manager below, then OpenRouter or Groq will answer.",
  "Dein Schlüssel wird auf diesem Gerät mit einem Passwort verschlüsselt gespeichert und nur an den eigenen Dienst geschickt – direkt aus dem Browser, ohne Umweg. Es gelten dieselben Kostenregeln wie am PC (nur kostenlose Modelle, Höchstpreis 0, kein Aufladen). Sicherer ist der PC: Ist er verbunden, benutzt JARVIS dessen Schlüssel.": "Your key is stored on this device encrypted with a password and only sent to its own service – straight from the browser, no detour. The same cost rules apply as on the PC (free models only, maximum price 0, no top-up). The PC is safer: when it is connected, JARVIS uses its key.",
  "Entsperren": "Unlock",
  "Entsperrt lassen, bis ich den Tab schließe": "Keep unlocked until I close the tab",
  "Entsperrt – OpenRouter und Groq sind bereit.": "Unlocked – OpenRouter and Groq are ready.",
  "Gesperrt": "Locked",
