  "Falls das nicht von selbst klappt: einmal das alte Passwort eingeben (danach nie wieder)": "If that does not happen by itself: enter the old password once (never again after that)",
  "Abgleich abgeschlossen": "Sync finished",
  "Automatische Synchronisierung": "Automatic sync",
  "Cloud nicht erreichbar": "Cloud not reachable",
  "Cloud verbunden": "Cloud connected",
  "Cloud wird geprüft …": "Checking the cloud …",
  "Der PC konnte nicht mit der Cloud verbunden werden.": "The PC could not be connected to the cloud.",
  "Der PC „{n}“ hat seine Daten zuletzt {w} in die Cloud übertragen. Dieses Gerät zeigt genau diesen Stand – auch wenn der PC jetzt aus ist.": "The PC “{n}” last uploaded its data to the cloud {w}. This device shows exactly that state – even while the PC is off.",
  "Dieser PC ist mit dem Konto „{u}“ verbunden und überträgt Änderungen automatisch (sofort nach einer Änderung, zusätzlich alle 30 Sekunden).": "This PC is connected to the account “{u}” and uploads changes by itself (right after a change, plus every 30 seconds).",
  "Dieser PC ist noch nicht mit dem Konto verbunden – deshalb liegen seine Daten nicht in der Cloud.": "This PC is not connected to the account yet – so its data is not in the cloud.",
  "Melde dich oben mit deinem Cloud-Konto an – dann hält die Cloud den letzten Stand deines PCs für alle deine Geräte bereit, auch bei ausgeschaltetem PC.": "Sign in with your cloud account above – then the cloud keeps your PC's latest state ready for all your devices, even while the PC is off.",
  "Noch hat kein PC Daten in die Cloud übertragen. Sobald der PC-Begleiter mit diesem Konto verbunden ist und läuft, geschieht das von selbst.": "No PC has uploaded data to the cloud yet. As soon as the PC companion is connected to this account and running, this happens by itself.",
  "Noch nicht synchronisiert": "Not synced yet",
  "Nur Funktionen, die auf dem Windows-PC etwas ausführen (Spiel starten, Soundboard, Fernsteuerung …), brauchen eine aktive PC-Verbindung. Alles andere siehst und änderst du auch ohne PC.": "Only functions that run something on the Windows PC (starting a game, soundboard, remote control …) need an active PC connection. Everything else you can see and change without the PC too.",
