  "{n} Änderung(en) von diesem Gerät warten darauf, in die Cloud zu kommen. Sie werden automatisch gesendet, sobald die Verbindung da ist – nichts geht verloren.": "{n} change(s) from this device are waiting to reach the cloud. They are sent automatically as soon as the connection is back – nothing is lost.",
