  "Sobald JARVIS etwas merkt, erscheint es hier.": "As soon as JARVIS remembers something, it appears here.",
  "Zuletzt gemerkt": "Recently remembered",
  "Zum Beispiel C:\\Users\\Name\\Documents\\JARVIS-MEMORY – der Ordner wird angelegt, falls es ihn nicht gibt. Ein vorhandener Obsidian-Vault geht auch.": "For example C:\\Users\\Name\\Documents\\JARVIS-MEMORY – the folder is created if it does not exist. An existing Obsidian vault works too.",
