  "Noch nichts gesendet": "Nothing sent yet",
  "Schicke einen Link oder Text vom Handy oder Tablet an deinen PC. Links öffnen sich auf Wunsch gleich im Browser des PCs; Text bleibt hier zum Kopieren stehen.": "Send a link or text from your phone or tablet to your PC. Links can open right away in the PC's browser; text stays here to copy.",
  "Vom Handy gesendet": "Sent from the phone",
  "Zum Senden muss der PC verbunden sein.": "The PC must be connected to send.",
  "am PC geöffnet": "opened on the PC",
  "Öffnet ihn im Standard-Browser des PCs. Aus: er landet nur in der Liste.": "Opens it in the PC's default browser. Off: it only lands in the list.",
  "Gesendet": "Sent",
  "Am PC geöffnet": "Opened on the PC",
  "Anmeldung fehlgeschlagen: {m}": "Sign-in failed: {m}",
  "Bei der Registrierung kann eine Bestätigung per E-Mail nötig sein – danach meldest du dich hier an.": "Registration may ask for an e-mail confirmation – after that, sign in here.",
  "Bitte gib eine gültige E-Mail-Adresse an.": "Please enter a valid e-mail address.",
  "Cloud ist für diese App noch nicht eingerichtet.": "The cloud is not set up for this app yet.",
  "Cloud-Speicherung ist in dieser App-Version nicht eingerichtet. Deshalb liegt das Konto auf deinem PC.": "Cloud storage is not set up in this app version. That is why the account lives on your PC.",
  "Das Konto „{u}“ wird aus der Cloud gelöscht. Die Daten auf diesem Gerät bleiben.": "The account “{u}” is deleted from the cloud. The data on this device stays.",
  "Das Passwort ist zu kurz oder zu schwach.": "The password is too short or too weak.",
  "Dein Konto liegt in der Cloud – nicht auf deinem PC. Deshalb kannst du dich auch anmelden, wenn der PC aus ist. Es kommt mit: Design, Startseite und Leiste, Sprache, Gamer-Pass, Zähler, Pausen-Erinnerung, der Ordner und die Regeln für JARVIS MEMORY, dein Wetter-Ort und die KI-Auswahl. Alles wird schon im Browser verschlüsselt, Passwort und Schlüssel bleiben auf dem Gerät. Spiele, Deck, Wunschliste und Kalender brauchen weiterhin den PC.": "Your account lives in the cloud – not on your PC. That is why you can sign in while the PC is off. It brings along: design, home screen and bar, language, gamer pass, counters, break reminder, the folder and rules for JARVIS MEMORY, your weather location and the AI choice. Everything is encrypted in the browser first, and the password and key stay on the device. Games, deck, wishlist and calendar still need the PC.",
  "Der Cloud-Dienst antwortet nicht – bitte Internetverbindung prüfen.": "The cloud service is not responding – please check the internet connection.",
  "Der Cloud-Dienst ist erreichbar.": "The cloud service is reachable.",
  "Die Cloud-Datenbank ist nicht verbunden – im Worker die D1-Bindung DB eintragen.": "The cloud database is not connected – add the D1 binding DB in the Worker.",
  "Der Cloud-Dienst meldet einen Fehler – bitte später erneut prüfen.": "The cloud service reports an error – please check again later.",
  "Der Cloud-Dienst antwortet unerwartet – bitte später erneut prüfen.": "The cloud service responds unexpectedly – please check again later.",
  "Der Cloud-Dienst hat keine gültige Anmeldung zurückgegeben.": "The cloud service did not return a valid sign-in.",
  "Die Anmeldung ist abgelaufen – bitte neu anmelden.": "The sign-in has expired – please sign in again.",
  "Die Kontodaten sind zu groß für die Cloud (Hintergrundbild verkleinern).": "The account data is too large for the cloud (make the background picture smaller).",
  "Diese E-Mail ist schon registriert – bitte anmelden.": "This e-mail is already registered – please sign in.",
  "Dieser Browser kann keine Verbindung zur Cloud aufbauen.": "This browser cannot connect to the cloud.",
