  "Der Geheimcode ist falsch.": "The secret code is wrong.",
  "Der Geheimcode ist gesetzt: Das Passwort wird nur nach Eingabe des Codes angezeigt.": "The secret code is set: the password is only shown after entering the code.",
  "Die beiden neuen Passwörter sind nicht gleich.": "The two new passwords do not match.",
  "Dieses Gerät kennt dein Passwort noch nicht (du hast dich früher angemeldet). Gib es einmal ein – dann kannst du es hier jederzeit ansehen.": "This device does not know your password yet (you signed in earlier). Enter it once – then you can see it here any time.",
