  "Neues Passwort wiederholen": "Repeat new password",
  "Passwort gemerkt.": "Password remembered.",
  "Passwort geändert.": "Password changed.",
  "Passwort ändern": "Change password",
  "Verbergen": "Hide",
  "Vergisst du den Geheimcode, hilft nur erneutes Anmelden mit dem Passwort.": "If you forget the secret code, only signing in again with the password helps.",
  "Zugangsdaten": "Credentials",
  "gesetzt": "set",
  "Ändern oder entfernen": "Change or remove",
  "Weiteres Konto hinzufügen": "Add another account",
  "Stimme testen": "Test voice",
  "Test läuft: Du hörst dich selbst in der gewählten Stimme – nur mit Kopfhörern, sonst pfeift es. Zu Discord geht dabei nichts. Wechsle die Stimme, während du sprichst.": "Test running: you hear yourself in the chosen voice – headphones only, otherwise it will whistle. Nothing goes to Discord. Switch the voice while you talk.",
  "Stärke der Stimme: {v} %": "Voice strength: {v} %",
  "Stärke der Stimme": "Voice strength",
  "Weniger = du bleibst besser zu verstehen, mehr = die Stimme klingt extremer. Zum Anfang: 70 %.": "Less = easier to understand, more = a more extreme voice. To start with: 70 %.",
  "Automatisch bei Sprechpausen": "Automatic at speech pauses",
  "Der Schlüssel ist noch gesperrt – in der KI-Verwaltung entsperren.": "The key is still locked – unlock it in the AI manager.",
  "Die Stimmen aus deinem ElevenLabs-Konto. Nimm nur Stimmen, für die du die Rechte hast.": "The voices of your ElevenLabs account. Only use voices you have the rights to.",
  "Echte Stimme starten": "Start real voice",
  "Echte Stimmen (ElevenLabs)": "Real voices (ElevenLabs)",
  "Effekte (live)": "Effects (live)",
  "ElevenLabs-Schlüssel fehlt": "ElevenLabs key missing",
  "Erst das andere Programm, dann diese Seite: Hier als „Mikrofon“ das virtuelle Gerät des anderen Programms wählen, als Ausgabe das Kabel für Discord.": "The other program first, then this page: choose the other program’s virtual device as “Microphone” here, and the cable for Discord as the output.",
  "Erst diese Seite, dann das andere Programm: Hier als „Ausgabe an Discord“ das virtuelle Gerät des anderen Programms wählen (dessen Eingang), in Discord dessen Ausgang als Mikrofon.": "This page first, then the other program: choose the other program’s virtual device (its input) as “Output to Discord” here, and its output as the microphone in Discord.",
  "Letzte Verzögerung: {s} s · {n} Sätze · {m} s gesendet": "Last delay: {s} s · {n} sentences · {m} s sent",
  "Mit anderen Voice-Changern kombinieren": "Combine with other voice changers",
  "Nicht live wie die Effekte: Jeder Satz braucht ein bis drei Sekunden bis zur neuen Stimme, wie beim Funk. Die gesendete Sprechzeit zählt gegen das Guthaben deines ElevenLabs-Tarifs.": "Not live like the effects: each sentence takes one to three seconds until the new voice, like on the radio. The speech time sent counts against your ElevenLabs plan.",
  "Nimmt auf": "Recording",
  "Noch keine Stimmen geladen": "No voices loaded yet",
  "Noch nichts gesendet.": "Nothing sent yet.",
  "Sendet …": "Sending …",
  "Sprechen (halten)": "Talk (hold)",
  "Sprich jetzt …": "Speak now …",
  "Spricht": "Speaking",
  "Statt die Taste zu halten: Ein Satz wird aufgenommen, sobald du sprichst, und nach einer kurzen Pause gesendet. Mit Kopfhörern, sonst nimmt das Mikrofon deine Stimme aus den Lautsprechern wieder auf.": "Instead of holding the button: a sentence is recorded as soon as you speak and sent after a short pause. Use headphones, otherwise the microphone picks your voice up from the speakers again.",
  "Stimmen laden": "Load voices",
  "Trage deinen ElevenLabs-Schlüssel einmal in der KI-Verwaltung ein (Abschnitt „ElevenLabs auf diesem Gerät“). Er gilt dann auf allen Geräten deines Kontos.": "Enter your ElevenLabs key once in the AI manager (section “ElevenLabs on this device”). It then applies on all devices of your account.",
  "Voicemod, Voicemeeter, RVC/w-okada und ähnliche Programme haben ihr eigenes virtuelles Gerät. Du kannst sie hintereinanderschalten.": "Voicemod, Voicemeeter, RVC/w-okada and similar programs have their own virtual device. You can chain them.",
  "Zwei Programme nacheinander verzögern etwas mehr. Voicemod bietet keine offene Schnittstelle – es lässt sich nur so einbinden, nicht steuern.": "Two programs in a row add a little more delay. Voicemod has no open interface – it can only be chained this way, not controlled.",
