  "Tiefer Roboter mit hartem Klang": "Deep robot with a hard sound",
  "Wie eine Lautsprecher-Durchsage": "Like a loudspeaker announcement",
  "Laut, hallend, als stündest du im Stadion": "Loud and echoing, as if in a stadium",
  "Deine Stimme doppelt, leicht versetzt": "Your voice doubled, slightly offset",
  "Knisternde Funkdurchsage aus dem Cockpit": "Crackling radio call from the cockpit",
  "Als Mikrofon ist das Kabel selbst gewählt – bitte dein echtes Mikrofon wählen.": "The cable itself is chosen as the microphone – please choose your real microphone.",
  "Auf deinen Standard-Kopfhörern – bitte nur mit Kopfhörern, sonst pfeift es.": "On your default headphones – headphones only, otherwise it will whistle.",
  "Ausgabe an Discord": "Output to Discord",
  "Ausgabe steht auf dem Kabel – gut.": "Output is set to the cable – good.",
  "Ausgabe-Lautstärke": "Output volume",
  "Ausgabe-Lautstärke: {v} %": "Output volume: {v} %",
  "Ausgabegerät nicht wählbar": "Output device cannot be chosen",
  "Das hat nicht geklappt": "That did not work",
  "Das virtuelle Kabel: „CABLE Input“.": "The virtual cable: “CABLE Input”.",
  "Der Stimmenwechsler braucht Chrome oder Edge am PC (Echtzeit-Audio und Ausgabegerät wählen). Öffne die Seite dort.": "The voice changer needs Chrome or Edge on the PC (real-time audio and choosing the output device). Open the page there.",
  "Die Stimme geht gerade auf ein normales Gerät, nicht auf das virtuelle Kabel. Wähle unten als Ausgabe „CABLE Input“ – sonst hörst nur du dich.": "Your voice currently goes to a normal device, not to the virtual cable. Choose “CABLE Input” as the output below – otherwise only you can hear yourself.",
  "Dieser Browser kann das nicht": "This browser cannot do that",
  "Dieser Browser kann den Ton nicht an das virtuelle Kabel schicken. Chrome oder Edge nehmen.": "This browser cannot send the sound to the virtual cable. Use Chrome or Edge.",
  "Discord hört dich so nicht": "Discord cannot hear you like this",
  "Du": "You",
  "Ein virtuelles Audiokabel installieren – z. B. „VB-Audio Virtual Cable“ (kostenlos, von vb-audio.com). Danach hier „Geräte laden“.": "Install a virtual audio cable – e.g. “VB-Audio Virtual Cable” (free, from vb-audio.com). Then tap “Load devices” here.",
  "Feinabstimmung der Tonhöhe": "Pitch fine tuning",
  "Feinabstimmung der Tonhöhe: {v} Halbtöne": "Pitch fine tuning: {v} semitones",
  "Filtert Tastaturklappern und Rauschen. Gilt nach dem nächsten Start.": "Filters keyboard clatter and noise. Applies after the next start.",
  "Geräte laden": "Load devices",
  "Geräte wechseln gilt nach dem nächsten Start.": "Changing devices applies after the next start.",
  "Gestoppt": "Stopped",
  "Hier „Stimmenwechsler starten“ tippen.": "Tap “Start voice changer” here.",
  "In Discord → Einstellungen → Sprache & Video: Eingabegerät = „CABLE Output“. Das kann keine App von außen prüfen – mit dem Mikrofontest von Discord kontrollieren.": "In Discord → Settings → Voice & Video: input device = “CABLE Output”. No app can check that from outside – verify it with Discord’s microphone test.",
  "Läuft weiter, wenn du eine andere Seite öffnest – nur wenn du das Fenster schließt, hört es auf.": "Keeps running when you open another page – it only stops when you close the window.",
  "Macht die gewählte Stimme etwas höher oder tiefer.": "Makes the chosen voice a little higher or lower.",
  "Mich selbst hören": "Hear myself",
  "Mikrofon-Lautstärke": "Microphone volume",
  "Oben als „Ausgabe an Discord“ das Kabel („CABLE Input“) wählen.": "Choose the cable (“CABLE Input”) above as “Output to Discord”.",
  "Pegel": "Level",
  "Pegel Ausgang": "Output level",
  "Pegel Mikrofon": "Microphone level",
  "Rauschunterdrückung": "Noise suppression",
  "So hören dich deine Freunde": "How your friends hear you",
  "Sprich in Discord mit einer anderen Stimme – tief, hoch, wie ein Roboter oder Monster. Dein Mikrofon läuft durch diese Seite und geht über ein virtuelles Kabel an Discord.": "Talk in Discord with a different voice – deep, high, like a robot or a monster. Your microphone runs through this page and goes to Discord over a virtual cable.",
  "Standard-Ausgabe (nur du hörst dich)": "Default output (only you hear yourself)",
  "Standard-Mikrofon": "Default microphone",
  "Stimmenwechsler": "Voice changer",
  "Stimmenwechsler starten": "Start voice changer",
  "Tipp: Discords eigene Rauschunterdrückung und Echo-Entfernung kannst du dann ausschalten, die Seite macht das schon.": "Tip: you can switch off Discord’s own noise suppression and echo removal – this page already does that.",
