  "Telefon": "Telephone",
  "Dünn wie am alten Telefon": "Thin like on an old phone",
  "Megafon": "Megaphone",
  "Laut und verzerrt": "Loud and distorted",
  "Höhle": "Cave",
  "Du stehst in einer großen Halle": "You are standing in a big hall",
  "Echo": "Echo",
  "Jedes Wort kommt zurück": "Every word comes back",
  "Dazu habe ich keine Antwort bekommen.": "I did not get an answer to that.",
  "Cloud & Synchronisierung": "Cloud & sync",
  "Cloud-Konto": "Cloud account",
  "Dazu kommen der Ordner und die Regeln für JARVIS MEMORY, dein Wetter-Ort und die KI-Auswahl – also welcher Anbieter zuerst antwortet. Auf dem Handy ist damit alles schon eingerichtet, bevor der PC verbunden ist. Auch deine KI-Schlüssel reisen mit – verschlüsselt, und nur für dieses Konto.": "Also included are the folder and rules for JARVIS MEMORY, your weather place and the AI choice – which provider answers first. On the phone everything is already set up before the PC is connected. Your AI keys travel along too – encrypted, and only for this account.",
  "Deine KI-Schlüssel gehören zu diesem Konto: Sie sind auf jedem Gerät da, auf dem du angemeldet bist – und ein anderes Konto sieht sie nie. Im Browser werden sie verschlüsselt, bevor sie ins Konto gehen; die Cloud kann sie nicht lesen. Ins Backup-Datei kommen sie nicht.": "Your AI keys belong to this account: they are there on every device where you are signed in – and another account never sees them. They are encrypted in the browser before they go into the account; the cloud cannot read them. They are not part of the backup file.",
  "KI-Schlüssel dieses Kontos": "AI keys of this account",
  "Konto wechseln": "Switch account",
  "Noch kein Schlüssel in diesem Konto – in der KI-Verwaltung eintragen, dann ist er auf all deinen Geräten da.": "No key in this account yet – enter one in the AI manager and it will be on all your devices.",
  "PC bereit": "PC ready",
  "Profil, Cloud & KI-Schlüssel öffnen": "Open profile, cloud & AI keys",
  "Wechsle …": "Switching …",
  "Android-App": "Android app",
  "Dieselbe Seite als App fürs Handy – eigener Speicher, bleibt angemeldet und prüft selbst auf Updates wie am PC.": "The same page as an app for the phone – its own storage, stays signed in and checks for updates itself like the PC.",
  "Installiert: Version {v}": "Installed: version {v}",
  "APK herunterladen": "Download APK",
  "Version {v} ist verfügbar – in der App oben auf „Installieren“ tippen.": "Version {v} is available – tap “Install” at the top of the app.",
