  "Neueste Version: {v}. Im Browser wird nichts installiert – die App aktualisiert sich selbst.": "Latest version: {v}. Nothing is installed in the browser – the app updates itself.",
  "Android fragt beim Installieren einmal nach – ein stilles Selbst-Update erlaubt Android ohne Systemrechte nicht.": "Android asks once when installing – a silent self-update is not allowed without system rights.",
  "Dazu kommen der Ordner und die Regeln für JARVIS MEMORY, dein Wetter-Ort und die KI-Auswahl – also welcher Anbieter zuerst antwortet. Auf dem Handy ist damit alles schon eingerichtet, bevor der PC verbunden ist. KI-Schlüssel und API-Schlüssel liegen nie im Konto.": "On top of that come the folder and rules for JARVIS MEMORY, your weather location and the AI choice – meaning which provider answers first. On the phone everything is therefore already set up before the PC is connected. AI keys and API keys are never in the account.",
  "Dieses Konto ist auf diesem Gerät nicht gespeichert – bitte einmal mit Passwort anmelden.": "This account is not stored on this device – please sign in once with the password.",
  "Gedächtnis im Konto": "Memory in the account",
  "Im Konto gespeichert": "Saved in the account",
  "Noch nicht eingerichtet": "Not set up yet",
  "Der Ordner und die Regeln reisen im Konto mit – du kannst sie hier auch ohne PC einstellen. Die Notizen selbst bleiben auf dem PC; Ordner und Regeln setzt der PC automatisch, sobald er verbunden ist.": "The folder and the rules travel with the account – you can set them here even without the PC. The notes themselves stay on the PC; folder and rules are applied by the PC by itself as soon as it is connected.",
  "Ordner des Gedächtnisses": "Memory folder",
  "Diese Einstellung gilt für alle Geräte deines Kontos. Den Ordner legt der PC an, sobald er verbunden ist.": "This setting applies to every device of your account. The PC creates the folder as soon as it is connected.",
  "Auf diesen PC übernehmen": "Apply on this PC",
  "Auf dem PC übernommen": "Applied on the PC",
  "Gedächtnis auf dem PC eingerichtet": "Memory set up on the PC",
  "Wetter-Ort auf dem PC eingerichtet": "Weather location set on the PC",
  "KI-Auswahl auf dem PC übernommen": "AI selection applied on the PC",
  "Reihenfolge und Betriebsart reisen im Konto mit und werden auf dem PC beim Verbinden gesetzt. KI-Schlüssel bleiben auf dem Gerät.": "The order and the mode travel with the account and are set on the PC when it connects. AI keys stay on the device.",
  "Reihenfolge und Betriebsart reisen mit, sobald du im Konto angemeldet bist. KI-Schlüssel bleiben auf dem Gerät.": "The order and the mode travel along as soon as you are signed in to the account. AI keys stay on the device.",
  "Ordner und Regeln": "Folder and rules",
  "Der PC hat sie beim letzten Verbinden übernommen: {w} ({t}).": "The PC took them over at the last connection: {w} ({t}).",
  "Beim letzten Verbinden hat der PC nicht geantwortet – der nächste Verbindungsaufbau versucht es erneut.": "The PC did not answer at the last connection – the next connection tries again.",
  "Beim letzten Verbinden war auf dem PC schon alles gleich – nichts zu übernehmen.": "At the last connection the PC already had everything the same – nothing to take over.",
  "Beim letzten Verbinden automatisch aus dem Konto übernommen: {w} ({t}).": "Taken over from the account automatically at the last connection: {w} ({t}).",
  "Ohne PC ist hier nur das Einrichten möglich – gemerkt und nachgeschlagen wird erst, wenn der PC verbunden ist.": "Without the PC you can only set this up here – noting and looking up starts once the PC is connected.",
  "Wo die Daten liegen": "Where the data lives",
  "Standardmäßig liegen die Kontodaten im Nexus-Cloud-Dienst. Du kannst stattdessen deinen eigenen Cloudflare-Dienst betreiben: Dann liegen die Daten in deiner D1-Datenbank, und Handy wie PC melden sich dort an, ohne dass der PC laufen muss.": "By default the account data lives in the Nexus cloud service. You can run your own Cloudflare service instead: the data then lives in your D1 database, and phone and PC sign in there without the PC having to run.",
  "Nexus-Cloud": "Nexus Cloud",
  "Eigener Dienst": "Own service",
  "Adresse des Dienstes": "Service address",
  "Zum Beispiel https://nexus-cloud.dein-name.workers.dev – ohne Schrägstrich am Ende.": "For example https://nexus-cloud.your-name.workers.dev – without a trailing slash.",
  "Standard wiederherstellen": "Restore default",
  "Eigenen Cloudflare-Dienst einrichten": "Set up your own Cloudflare service",
  "1. Im Cloudflare-Dashboard eine D1-Datenbank anlegen.": "1. Create a D1 database in the Cloudflare dashboard.",
  "2. Den Ordner cloud-account-worker als Worker veröffentlichen, die Datenbank als Bindung DB eintragen und ALLOWED_ORIGINS auf * setzen.": "2. Publish the cloud-account-worker folder as a Worker, bind the database as DB and set ALLOWED_ORIGINS to *.",
  "3. Die Adresse des Workers hier eintragen, speichern und auf Handy und PC mit demselben Konto anmelden.": "3. Enter the Worker address here, save, and sign in on phone and PC with the same account.",
  "Der API-Schlüssel bleibt im Worker – Cloudflare erlaubt den direkten Datenbank-Zugriff aus dem Browser nicht. Dein Schlüssel wird nie an diese App geschickt.": "The API key stays in the Worker – Cloudflare does not allow direct database access from the browser. Your key is never sent to this app.",
  "Worker-Code auf GitHub": "Worker code on GitHub",
  "Zum Wechseln bitte erst abmelden – deine lokalen Daten bleiben dabei erhalten.": "Please sign out before switching – your local data stays.",
  "Der mitgelieferte Dienst ist voreingestellt. Ein eigener Dienst lohnt sich, wenn deine Daten in deinem Cloudflare-Konto liegen sollen.": "The included service is preset. An own service is worthwhile if your data should live in your Cloudflare account.",
  "Speicherort": "Storage location",
